window.SITE_DATA={"generatedFrom":"plugins/","plugins":[{"name":"bossdream-core","version":"1.0.0","description":"Motor agnostico de desarrollo asistido: Delivery Cycle, pipeline de calidad, Completion Criteria por hooks deterministas, documentacion IA-friendly, y gobernanza de documentos de negocio del SDLC (Understanding/Requirements/Test approach con Document Validation por documento)."},{"name":"bossdream-dotnet","version":"0.1.0","description":"Pack de lenguaje .NET: pipeline, CI, editorconfig, permisos y snippet de CLAUDE.md para proyectos dotnet."},{"name":"bossdream-nodejs","version":"0.1.0","description":"Pack de lenguaje Node/TS: pipeline, CI, editorconfig, permisos y snippet de CLAUDE.md para proyectos npm (JS/TS, Vue/React/Tauri sobre este pack)."}],"commands":[{"name":"bossdream-implement","group":"Ciclo de entrega","description":"Ejecuta el plan.md de la feature activa INCREMENT POR INCREMENT. Por cada increment implementa, corre el pipeline del increment, y PARA a pedir permiso con un informe de cambios justificado. NO commitea (los commits son del usuario). NO auto-invocable: solo lo corre el usuario, y correrlo ES su autorizacion explicita para implementar. TRIGGER — el usuario lo ejecuta tras /bossdream-plan.","args":[],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-init","group":"Arranque","description":"Materializa la capa de proyecto de BossDream (docs/, plans/, .claude, pipeline.json, completion.json, CI) en el repo actual, de forma idempotente y reutilizando lo que ya exista. Al terminar indica al usuario que archivos debe rellenar y donde.","args":[],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-learning-review","group":"Mantenimiento","description":"Corre el gate de 4 etapas de bossdream-learning (evidence_gate/pattern_consistency_gate deterministas + validacion/aprobacion humana) sobre un patron detectado, y si pasa, ofrece publicarlo como tutorial procedural. TRIGGER — el usuario quiere revisar si una operacion repetida (ej. registrar TC-XXX) ya califica para publicarse como tutorial reusable.","args":["slug"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-mode","group":"Ciclo de entrega","description":"Declara explicitamente el tipo de la tarea actual (el modo). Modos NO-editables (plan, document, review) bloquean toda edicion de codigo. Modos editables sin spec (spike, explore, bugfix, chore) permiten editar rutas de dominio sin frenar para arreglos ad-hoc. `feature` (o sin modo) exige spec en rutas de dominio. `clear` borra el modo. Para EJECUTAR un plan usa `/bossdream-implement`, no este comando.","args":["mode"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-new","group":"Arranque","description":"Crea un proyecto NUEVO desde cero con gobernanza BossDream desde el dia uno (greenfield). Toma la idea del proyecto (inline) o un archivo de requerimientos como semilla, planea, guia el scaffold del esqueleto (receta de stack-pack o herramienta nativa), y cablea la gobernanza. Para instalar BossDream sobre un proyecto que YA existe, usa /bossdream-init. TRIGGER — el usuario quiere arrancar un proyecto nuevo.","args":["nombre","idea"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-override","group":"Gobernanza de negocio","description":"Llave de emergencia - destraba UNA invocacion de /bossdream-plan o /bossdream-implement bloqueada por validation-lock.ps1, sin desactivar el gate para el resto del proyecto. TRIGGER - el usuario necesita avanzar de urgencia (ej. fix de produccion) con validation.json.overallStatus en blocked y no puede esperar a resolver los hallazgos de Document Validation.","args":["motivo","alcance"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-plan","group":"Ciclo de entrega","description":"De una historia cruda del usuario a un plan ejecutable por increments. Investiga (codigo + web), verifica impacto cross-flow, propone 2-3 opciones y construye el plan INCREMENTALMENTE: cada increment pasa su revision de diseno antes de escribirse al MD. Escala la ceremonia al tamano (trivial->directo, task->ligero, grande->deep-plan). TRIGGER — el usuario describe QUE quiere lograr (una historia/necesidad), no una solucion ya hecha. NOTA: se llama bossdream-plan (NO plan) para no colisionar con el Plan Mode NATIVO de Claude Code.","args":["historia"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-project","group":"Gobernanza de negocio","description":"Arranca un proyecto de negocio nuevo con gobernanza de documentos SDLC. Desde una idea o documentos de entrada, clasifica Simple/Medio/Complejo, propone Epics/Features cuando aplique, genera requirements.md (incluida su seccion de Reglas de negocio) via docs-rewrite reusado, y deja tests/test-approach.md crudo, con placeholders y el aviso de validacion estricta ya integrado en la plantilla. TRIGGER — el usuario quiere iniciar la documentacion de negocio de una iniciativa nueva, antes de poder correr /bossdream-validate o /bossdream-plan sobre ella.","args":["contexto"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-qa-mode","group":"Ciclo de entrega","description":"Fija el modo de QA persistente del proyecto (`bossdream.json > qa.mode`) que usan `qa-run` y el QA Increment. Valores optimo, agresivo o costoso (default). No es `/bossdream-mode`, que declara el tipo de tarea. Sin argumento muestra el modo actual.","args":["modo"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-report","group":"Gobernanza de negocio","description":"Genera overview.md/understanding.md del proyecto activo bajo demanda, en docs/reports/<slug>/ — fuera del alcance de validation-check.ps1. Reportes humanos legibles (que se entendio y que se va a construir), reusando las plantillas de templates/_PROJECT_TEMPLATE/ a partir de requirements.md/traceability.json/tests/test-approach.md. TRIGGER — el usuario quiere un resumen humano del proyecto activo, sin que eso agregue documentos al gate de Document Validation.","args":[],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-set-active-project","group":"Gobernanza de negocio","description":"Activa, cambia o desactiva el proyecto activo (.claude/.active-project) — puntero LOCAL por desarrollador, nunca compartido via git. Sin argumento, informa el estado actual. TRIGGER — el usuario quiere retomar un proyecto que otro dev ya documento, cambiar de proyecto para apoyar en otro, o volver al modo normal (bossdream-plan/bossdream-implement sin gobernanza de proyecto) para una tarea suelta.","args":["accion"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-skill-exploration","group":"Mantenimiento","description":"Audita/actualiza el catalogo completo de skills del proyecto — mapea el repo entero, corre tech-debt a nivel de todo el proyecto, y disena con el usuario (via brainstorming) cada skill nueva o desactualizada que tech-debt confirme. TRIGGER — proceso unico y puntual: el usuario lo invoca cuando quiere auditar/actualizar el catalogo completo de skills del proyecto, sin instruccion adicional del usuario sobre que explorar.","args":[],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-sync","group":"Arranque","description":"Reconcilia los archivos gestionados por el framework (wiring de hooks en settings, plantillas de pipeline/completion, esqueletos de docs) con la version actual del plugin, sin tocar el contenido del equipo ni del usuario.","args":[],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-sync-models","group":"Arranque","description":"Sincroniza el `model:` del frontmatter de cada agente en `plugins/bossdream-core/agents/` con `bossdream.json > models`. Ya corre automatico via hook al editar bossdream.json; este comando lo fuerza a mano.","args":[],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-testcase","group":"Gobernanza de negocio","description":"Genera un nuevo caso de prueba (TC-XXX.md) para el proyecto activo, presentado al usuario para aprobar/corregir/rechazar antes de registrarlo. Cada corrida reabre validation.json a blocked. TRIGGER — el usuario quiere agregar un caso de prueba formal (Medio/Complejo) a un proyecto ya scaffoldeado.","args":["escenario"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"bossdream-update-docs","group":"Gobernanza de negocio","description":"Registra los cambios que el usuario hizo a mano en los documentos del proyecto activo (ediciones a documentos existentes, o alcance nuevo que aparecio y necesita integrarse a la jerarquia Epic/Feature/US). Reabre el Document Validation cuando corresponde. TRIGGER — el usuario edito documentos manualmente y quiere que el sistema se entere, o describe alcance nuevo que todavia no esta escrito en requirements.md.","args":["alcance_nuevo"],"userOnly":false,"tools":[],"model":"","source":""},{"name":"bossdream-validate","group":"Gobernanza de negocio","description":"Corre el pipeline de Document Validation batcheado por check (no documento por documento) sobre el proyecto activo, con la profundidad que le toque segun su clasificacion S/M/C. Repetible hasta que todos los documentos queden verified. TRIGGER — el usuario termino de revisar/ajustar los documentos generados por /bossdream-project (especialmente tests/test-approach.md) y quiere desbloquear /bossdream-plan.","args":[],"userOnly":true,"tools":[],"model":"","source":""},{"name":"helpers","group":"Arranque","description":"Instala las herramientas companeras recomendadas de BossDream (ponytail, HEADROOM, caveman) — per-maquina y opcionales. NO viajan en el plugin porque no son portables; este comando ayuda a instalarlas. Presenta el menu, el usuario elige cuales, corres los pasos y creditas a cada proyecto. TRIGGER — el usuario quiere instalar las herramientas companeras.","args":[],"userOnly":true,"tools":[],"model":"","source":""}],"skills":[{"name":"adr-new","group":"Documentación","description":"Crea un Architecture Decision Record en docs/adr/ con formato MADR (numeracion consecutiva, status, context, decision, consequences). TRIGGER — se tomo una decision arquitectonicamente significativa, se cambio una convencion o se descarto una opcion con justificacion. El flujo (Fase 4) lo exige al tocar codigo legado.","args":["title"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"arch","group":"Ciclo de entrega","description":"Consultor de arquitectura con trade-offs reales y decisiones concretas. Maximo 2 opciones, recomendacion, riesgos y pasos. TRIGGER — decision de arquitectura o diseno de una solucion no trivial (fase 1 del flujo `bossdream`).","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"bossdream","group":"Ciclo de entrega","description":"Delivery Cycle (9 phases) + Simplicity Ladder para desarrollo riguroso en cualquier proyecto. Planificacion (dimensionar contexto + razonamiento estructurado + reto senior + arquitectura), busqueda de contexto en cascada barata, cuestionamiento y reuso, impacto sobre lo establecido, implementacion, auditoria de codigo (bossdream-solid-auditor), auditoria visual (bossdream-design-auditor), re-chequeo final y verificacion en vivo. TRIGGER — invocar ANTES de tocar nada cuando el cambio no es trivial (>1 archivo o >15 lineas netas), hay decision de arquitectura, ambiguedad de interpretacion, o intencion de crear algo nuevo. SKIP — pregunta informativa que no toca codigo, consulta trivial de una linea, o tooling/meta.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"bossdream-qa-planner","group":"Pruebas y QA","description":"Invoca al agente bossdream-qa-planner para emitir un veredicto ACCEPTED/REJECTED sobre la calidad de pruebas de una implementacion, incluso con tests/coverage/mutation en verde. TRIGGER — el usuario pide una autoridad de QA que revise si una implementacion esta realmente probada, no solo si los tests pasan.","args":["run"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"brainstorming","group":"Ciclo de entrega","description":"Convierte una idea cruda en un diseno aprobado por el humano ANTES de escribir codigo. Preguntas socraticas de una en una, 2-3 enfoques con trade-offs, aprobacion del diseno seccion por seccion, y escribe plans/<feature>/design.md. Gate duro: no implementar ni hacer scaffold hasta que el humano apruebe. TRIGGER — inicio de una feature o cambio no trivial sin diseno acordado; antecede a /plan-new y al Plan Mode nativo.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"context-router","group":"Ciclo de entrega","description":"Protocolo de economia de contexto — antes de leer un archivo completo, escala por niveles baratos primero (artefacto, resumen, mapa, simbolo, rango) y solo cae a archivo completo si ninguno responde. No es un comando que se invoca aparte, es una disciplina que toda skill/agente sigue cuando va a leer codigo o documentos. Registra cada consulta resuelta (en cualquier nivel) via context-router-log.ps1; solo el nivel archivo_completo carga una razon. TRIGGER — implicito, en cualquier punto donde una skill/agente este por hacer Read directo de un archivo completo.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"ctx","group":"Ciclo de entrega","description":"Dimensiona el contexto minimo necesario para una tarea antes de buscar o codear, para ahorrar tokens. Lista archivos minimos con lineas exactas, preguntas clave, que excluir, dependencias ocultas y complejidad. TRIGGER — al inicio de cualquier tarea no trivial (fase 0 del flujo `bossdream`), antes de disparar busquedas o lecturas amplias.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"docs-rewrite","group":"Documentación","description":"Transforma documentacion informal del usuario en documentacion estructurada IA-friendly sin inventar ni perder ideas. Recorre docs del proyecto, valida contra el codigo, detecta contradicciones/duplicidad/obsolescencia, pregunta ante ambiguedad, reorganiza segun Diataxis, mantiene referencias cruzadas y extrae decisiones a ADRs. TRIGGER — el usuario dejo notas en docs/_inbox/, pide ordenar/reescribir la documentacion, o el pipeline corre `docs-rewrite --check`. Modo --check es read-only para CI.","args":["mode"],"userOnly":false,"tools":[],"model":"","source":""},{"name":"epic-planner","group":"Gobernanza de negocio","description":"Agrupa las capacidades detectadas en el contexto de entrada de un proyecto en candidatos de Epic (solo Complejo) y Feature (Medio+Complejo), presenta la propuesta al usuario en una sola tanda, y escribe el resultado confirmado en requirements.md + traceability.json. Nunca inventa una agrupacion sin mostrarla primero. TRIGGER — la invoca /bossdream-project al crear un proyecto, o /bossdream-update-docs cuando aparece alcance nuevo que no encaja en la jerarquia ya definida.","args":["contexto"],"userOnly":false,"tools":[],"model":"","source":""},{"name":"execution-checks","group":"Ciclo de entrega","description":"Corre el Execution Checks (4 chequeos que demuestran que un implementation.diff real cumple lo planeado, sin fuera de alcance, y esta correctamente probado). TRIGGER — el usuario pide validar un diff/implementacion antes de cerrar la tarea.","args":["plan","diff","check","scope"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"flow-test-gen","group":"Pruebas y QA","description":"Genera el catalogo combinatorio de Pruebas de Flujo (workflow/business process testing, saga pattern testing cuando hay rollback) para el QA Increment del proyecto activo, usando all-transitions/round-trip coverage (ISTQB) como criterio explicito. Presenta cada caso al usuario uno por uno para aprobar/corregir/rechazar, y una vez aprobados escribe las pruebas de integracion/E2E reales con el framework del stack-pack instalado. TRIGGER — /bossdream-implement, en el penultimo paso del QA Increment (mismo lugar donde test-gen se invoca en cualquier increment normal).","args":["proyecto"],"userOnly":false,"tools":[],"model":"","source":""},{"name":"gherkin-gen","group":"Pruebas y QA","description":"Genera los escenarios Gherkin (.feature) de una feature a partir de los criterios de aceptacion del spec.md. Adversarial primero, UN happy path al final, cada escenario con @cubre. Si el criterio es ambiguo o no define todo el camino, PREGUNTA en vez de inventar. TRIGGER — lo invoca plan-new, o cuando se agrega/modifica un flujo y hay que crear/actualizar sus escenarios.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"pipeline","group":"Calidad","description":"Corre el pipeline de calidad del proyecto (etapas ordenadas por costo/feedback) o explica su configuracion. TRIGGER — el usuario pide correr los checks, validar antes de done, o preguntar por el orden/estado del pipeline. El Stop hook ya lo corre solo en tier local antes de done.","args":["tier","skip"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"plan-checks","group":"Ciclo de entrega","description":"Corre el Plan Checks (10 gates que demuestran que un plan-draft.json realmente entiende el problema antes de aprobarse). TRIGGER — el usuario pide validar un plan antes de aprobarlo, o preguntar el estado de un gate concreto del Plan Checks.","args":["plan","gate"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"plan-new","group":"Ciclo de entrega","description":"Crea la carpeta plans/<feature>/ con spec.md (QUE + POR QUE), plan.md (COMO), tasks.md (tareas) y un .feature Gherkin, a partir de la plantilla. Marca la feature como activa para el Gate de tareas del Completion Criteria. TRIGGER — inicio de una feature nueva, o cuando el Gate 1 readiness pide una spec antes de implementar.","args":["feature"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"qa-increment","group":"Pruebas y QA","description":"Ejecuta el QA Increment/Testing como paso nombrado y separado del flujo de implementacion -- corre el Test Checks completo, despacha el veredicto real del QA Manager y bloquea el cierre del increment si el veredicto es REJECTED. TRIGGER -- el usuario pide cerrar una tarea/feature y llega al ultimo increment del plan, o pide literalmente \"corre el QA Increment\"/\"qa-increment\".","args":["run"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"qa-run","group":"Pruebas y QA","description":"Ejecuta las pruebas de los casos obligatorios del Test Inventory en uno de 3 modos (Optimo/Agresivo/Costoso), tomado de `--modo` o, si falta, de `bossdream.json > qa.mode` (default costoso). TRIGGER -- el usuario pide correr/generar las pruebas de un modulo ya inventariado, o pide literalmente \"qa-run\"/\"corre las pruebas del QA\".","args":["modo"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"repo-map","group":"Ciclo de entrega","description":"Genera .bossdream-project/repo-map.json bajo demanda traduciendo consultas reales al MCP codebase-memory (search_graph, trace_path, index_status) al schema de 7 campos (archivo, linea, consumidores, tests, dependencias, generado_en, stale). Es una capa fina sobre el MCP, no un indexador nuevo — codebase-memory ya cubre eso funcionalmente, lo unico que faltaba era el mapeo consulta-a-JSON. TRIGGER — cuando una skill/agente necesita \"que consume X\" / \"que tests cubren X\" y quiere resolverlo sin invocar el MCP directo ni abrir archivos (nivel 3 de la cascada de context-router).","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"rules-comentarios","group":"Calidad","description":"Politica universal de comentarios (tolerancia cero a comentarios que explican QUE hace el codigo, bloques multi-linea, breadcrumbs de IA y separadores decorativos). Companero en contexto del hook comment-check que la aplica de forma determinista. TRIGGER — antes de escribir o mostrar cualquier bloque de codigo en cualquier lenguaje.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"skill-exploration","group":"Documentación","description":"Auditoria completa y puntual del catalogo de skills del proyecto — mapea todo el repo, corre tech-debt a nivel de TODO el proyecto (no acotado a un flujo), y por cada duplicacion real confirmada disena con el usuario (brainstorming) la skill nueva o la actualizacion de una existente. TRIGGER — invocada por /bossdream-skill-exploration, nunca automatica.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"sobriety-audit","group":"Calidad","description":"Audita la sobriedad del framework - detecta componentes (agentes/gates/artefactos/plugins) que declaran reemplazar a otro ya existente sin justificacion. TRIGGER - el usuario pide revisar si BossDream tiene componentes duplicados o redundantes.","args":["scope","components"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"tech-debt","group":"Calidad","description":"Analiza el codigo que le apuntes (archivo, flujo, modulo) y concluye sobre deuda tecnica — informe priorizado por impacto con remediacion y esfuerzo. Read-only respecto al codigo, NO bloquea ni corre en el pipeline. Registra los hallazgos en el ledger docs/TECH_DEBT.md. TRIGGER — el usuario pide analizar deuda de un objetivo, o el toque NO-obligatorio de /bossdream-plan sobre los flujos que el plan toca.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"test-checks","group":"Pruebas y QA","description":"Corre el Test Checks (cadena fija de 5 etapas que demuestra que una implementacion esta realmente probada, no solo \"tests en verde\"). TRIGGER — el usuario pide validar que algo implementado esta correctamente probado antes de cerrarlo.","args":["run"],"userOnly":true,"tools":[],"model":"","source":""},{"name":"test-gen","group":"Pruebas y QA","description":"Genera pruebas unitarias para una funcion, un flujo o una funcionalidad, pensadas COMO USUARIO (no como programador) — adversarial primero, happy path al final. Cada prueba pasa un pipeline de calidad antes de crearse. Respeta las exenciones (el codigo trivial no se prueba). TRIGGER — el paso \"pruebas unitarias\" de un increment, o cuando el usuario pide generar/actualizar pruebas de una funcion o flujo.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"theme-first","group":"Calidad","description":"Gobierna los estilos en modo theme-first — cero valores de identidad visual quemados; todo sale de tokens/variables del tema. Antes de crear un token pasa un mini-pipeline (reusar, no duplicar, nombre semantico, preguntar ante casi-duplicado). Respeta exenciones y los estilos de vendor que el usuario no controla. TRIGGER — al escribir/modificar estilos, o el paso de UI de un increment.","args":[],"userOnly":false,"tools":[],"model":"","source":""},{"name":"traceability-sync","group":"Gobernanza de negocio","description":"Reconstruye .bossdream-project/traceability.json del proyecto activo desde los Markdown reales (requirements.md + tests/cases/*.md) cuando se sospecha que se desincronizo. El JSON es un cache derivado, nunca la fuente de verdad. TRIGGER — el usuario lo pide a demanda, o /bossdream-update-docs la invoca internamente tras un edit manual.","args":["proyecto"],"userOnly":false,"tools":[],"model":"","source":""},{"name":"validation-exemption-advisor","group":"Gobernanza de negocio","description":"Investiga un documento atascado en el gate de Document Validation, distingue si el documento tiene un defecto real (recomienda corregirlo) de si el criterio genuinamente no aplica (propone una exencion concreta), y solo escribe en validation.json tras autorizacion explicita del usuario sobre el texto exacto. TRIGGER — invocada por nombre, o aceptada explicitamente tras la sugerencia de validation-lock.ps1/validation-run al cruzar stuckThreshold.","args":["documento"],"userOnly":false,"tools":[],"model":"","source":""},{"name":"validation-run","group":"Gobernanza de negocio","description":"Orquesta la corrida completa del pipeline de Document Validation para el proyecto activo. Dispara validation-check.ps1 (deterministico), decide si hace falta el agente bossdream-document-auditor para la parte semantica, y arma la tanda de preguntas (≤3) o el listado completo de errores (>3) segun el umbral de validation-rules.json. TRIGGER — la invoca /bossdream-validate.","args":["proyecto"],"userOnly":false,"tools":[],"model":"","source":""}],"agents":[{"name":"bossdream-assumption-breaker","group":"Plan","description":"Auditor de supuestos sin evidencia en un plan. Se invoca fresco, 0 historial previo, recibiendo la ruta de un `plan-draft.json` extendido con `supuestos[]`/`evidencia[]`. Compara ambos arrays y reporta cualquier supuesto sin entrada correspondiente en evidencia.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_context7","mcp__plugin_bossdream-core_fetch"],"model":"haiku","source":"---\nname: bossdream-assumption-breaker\ndescription: Auditor de supuestos sin evidencia en un plan. Se invoca fresco, 0 historial previo, recibiendo la ruta de un `plan-draft.json` extendido con `supuestos[]`/`evidencia[]`. Compara ambos arrays y reporta cualquier supuesto sin entrada correspondiente en evidencia.\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_context7, mcp__plugin_bossdream-core_fetch\nmodel: haiku\n---\n\nEres un auditor adversarial de supuestos no verificados en planes tecnicos (`plan-draft.json`). No escribes codigo, no modificas nada, solo lees y das veredicto.\n\n## Que evaluas\n\nRecibes un `plan-draft.json` con los campos `supuestos[]` (afirmaciones asumidas por el plan) y `evidencia[]` (rutas/simbolos que respaldan supuestos).\n\nPara cada elemento de `supuestos[]`, busca si `evidencia[]` contiene una entrada que lo respalde. Un supuesto es un hallazgo cuando ninguna entrada de `evidencia[]` lo cubre — ni por ruta/simbolo citado, ni por mencion textual relacionada.\n\n## Reglas\n\n- **Solo lectura.** Tu salida es un veredicto, quien te invoco decide que hacer con el.\n- No inventes evidencia que no este en `evidencia[]` — un supuesto plausible sigue siendo un hallazgo si no tiene respaldo escrito.\n- Si `supuestos[]` esta vacio o ausente, no hay nada que auditar: `VERDICT: pass`.\n- Si `evidencia[]` esta vacio y `supuestos[]` tiene al menos un elemento, TODOS los supuestos son hallazgos.\n- Cuando hay mas de un supuesto sin respaldo, el `reason` cita el primero encontrado en orden del array (no los enumera todos) — mismo criterio de un hallazgo concreto por veredicto que usan los demas gates de este framework.\n\n## Veredicto — formato estructurado obligatorio\n\n```\nVERDICT: pass\n```\n\no\n\n```\nVERDICT: blocked | reason: el supuesto \"<texto literal del supuesto>\" no tiene ninguna entrada correspondiente en evidencia[]\n```\n\nLa ultima linea no vacia de tu respuesta es siempre el `VERDICT`. `reason` cita el texto literal del supuesto sin respaldo — nunca una descripcion generica. Devuelve solo esto, nada de ensayo largo.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `context7`: contrastar un supuesto sobre una libreria con su documentacion vigente.\n- `fetch`: traer una URL citada como evidencia.\n"},{"name":"bossdream-coder","group":"Implementación","description":"Implementador. Recibe un plan y tareas concretas ya decididas y las ejecuta en código; no reabre arquitectura ni decide alcance (eso se planificó antes). Se usa en la fase 5 del flujo `bossdream` para que el modelo grande no gaste tecleando boilerplate.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","Edit","Write","MultiEdit","Bash","mcp__plugin_bossdream-core_serena","mcp__plugin_bossdream-core_codebase-memory","mcp__plugin_bossdream-core_context7","mcp__plugin_bossdream-core_dbhub"],"model":"sonnet","source":"---\nname: bossdream-coder\ndescription: Implementador. Recibe un plan y tareas concretas ya decididas y las ejecuta en código; no reabre arquitectura ni decide alcance (eso se planificó antes). Se usa en la fase 5 del flujo `bossdream` para que el modelo grande no gaste tecleando boilerplate.\ntools: Read, Grep, Glob, Edit, Write, MultiEdit, Bash, mcp__plugin_bossdream-core_serena, mcp__plugin_bossdream-core_codebase-memory, mcp__plugin_bossdream-core_context7, mcp__plugin_bossdream-core_dbhub\nmodel: sonnet\n---\n\nEres el implementador. Recibes un plan (`plan.md`) y tareas (`tasks.md`) ya decididas; las ejecutas al pie de la letra.\n\n## Reglas\n\n- **No reabras arquitectura** ni cambies el alcance: eso ya se decidió en la planificación. Si algo del plan es imposible o ambiguo, párate y repórtalo — no improvises una decisión de diseño.\n- **Reusa antes de crear** (Simplicity Ladder): confirma con codebase-memory/LSP si ya existe algo antes de escribir nuevo.\n- **Política de comentarios**: cero comentarios que expliquen el QUÉ; el hook los bloquea igual, no pierdas turnos.\n- Marca las tareas de `tasks.md` conforme las completas.\n- Muestra evidencia (build/tests) al terminar; no afirmes que quedó sin correrlo.\n\nTu salida es código y el estado de las tareas, no prosa de diseño.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `serena`: navegar y editar por simbolo antes de leer archivos completos.\n- `codebase-memory`: buscar si ya existe lo que vas a crear y ver llamadores.\n- `context7`: documentacion vigente de la libreria antes de asumir una API.\n- `dbhub`: leer el esquema (solo lectura) cuando el increment toca persistencia.\n"},{"name":"bossdream-completeness-auditor","group":"Plan","description":"Se despacha en el Cierre de `/bossdream-plan` (Paso 6), UNA VEZ por plan completo -- nunca por increment. TRIGGER -- justo antes de anunciar \\\"Plan completo\\\" al usuario. Identifica los sistemas/dominios externos que el plan integra (ej. \\\"SVN\\\", \\\"Stripe\\\", \\\"un proveedor OAuth\\\") y, por cada uno, investiga con WebFetch sus requisitos DUROS de funcionamiento -- autenticacion, conexion/link de servidor, configuracion obligatoria, version minima compatible -- citando URL+fecha de cada fuente consultada. Cruza esos requisitos contra la cobertura real de `spec.md`/`plan.md`: si falta algo claramente obligatorio siempre, reporta un hallazgo bloqueante citando la fuente; si es ambiguo (depende del caso de uso del proyecto), NUNCA decide solo -- formula la pregunta exacta que debe hacerse al usuario. Si el plan no integra ningun sistema externo, devuelve veredicto vacio explicito.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","WebFetch","mcp__plugin_bossdream-core_context7","mcp__plugin_bossdream-core_fetch"],"model":"sonnet","source":"---\nname: bossdream-completeness-auditor\ndescription: \"Se despacha en el Cierre de `/bossdream-plan` (Paso 6), UNA VEZ por plan completo -- nunca por increment. TRIGGER -- justo antes de anunciar \\\"Plan completo\\\" al usuario. Identifica los sistemas/dominios externos que el plan integra (ej. \\\"SVN\\\", \\\"Stripe\\\", \\\"un proveedor OAuth\\\") y, por cada uno, investiga con WebFetch sus requisitos DUROS de funcionamiento -- autenticacion, conexion/link de servidor, configuracion obligatoria, version minima compatible -- citando URL+fecha de cada fuente consultada. Cruza esos requisitos contra la cobertura real de `spec.md`/`plan.md`: si falta algo claramente obligatorio siempre, reporta un hallazgo bloqueante citando la fuente; si es ambiguo (depende del caso de uso del proyecto), NUNCA decide solo -- formula la pregunta exacta que debe hacerse al usuario. Si el plan no integra ningun sistema externo, devuelve veredicto vacio explicito.\"\ntools: Read, Grep, Glob, WebFetch, mcp__plugin_bossdream-core_context7, mcp__plugin_bossdream-core_fetch\nmodel: sonnet\n---\n\nEres un auditor de completitud de dominio. No escribis nada, no invocas otras skills, no decidis si un requisito ambiguo es obligatorio -- solo investigas y reportas un veredicto.\n\n## Entrada\n\n`spec.md` y `plan.md` completos de la feature que se esta cerrando. Nunca un increment suelto, nunca el research-log de otra feature.\n\n## Como procesas\n\n1. **Identificas los sistemas/dominios externos** que el plan integra, a partir del texto completo de `spec.md`/`plan.md` (ej. \"SVN\", \"Stripe\", \"un proveedor OAuth\", \"una API de terceros\"). Si no identificas ninguno, terminas ahi con veredicto vacio.\n2. **Por cada sistema identificado**, investigas con `WebFetch` sus requisitos DUROS de funcionamiento: autenticacion, conexion/link de servidor, configuracion obligatoria, version minima compatible. Citas URL + fecha de cada fuente consultada -- nunca una afirmacion sin fuente.\n3. **Cruzas cada requisito encontrado** contra la cobertura real de `spec.md`/`plan.md`: ¿algun criterio de aceptacion o increment ya lo contempla? Si si, no es un hallazgo.\n4. **Por cada requisito NO cubierto**:\n   - Si la investigacion confirma que es SIEMPRE obligatorio para que el sistema funcione -> hallazgo bloqueante, citando la fuente.\n   - Si es ambiguo (depende del caso de uso del proyecto) -> nunca decides solo; formulas la pregunta EXACTA que deberia hacerse al usuario.\n\n## Reglas\n\n- Solo lectura + investigacion web. Nunca `Write`/`Edit`, nunca invocas otra skill o agente.\n- Toda afirmacion sobre un requisito cita URL + fecha de la fuente investigada -- sin excepcion.\n- Nunca decidis unilateralmente si un requisito ambiguo es obligatorio -- eso se pregunta al usuario, siempre.\n- Si no hay sistemas externos que el plan integre, el veredicto es vacio y explicito -- no fuerzas un hallazgo para no dejarlo vacio.\n\n## Veredicto -- formato estructurado obligatorio\n\nSin sistemas externos detectados:\n\n```\nVERDICT: pass | sin sistemas externos detectados\n```\n\nCon hallazgos, uno por linea:\n\n```\n{ sistema: <sistema>, requisito: <requisito duro no cubierto>, fuente_investigada: \"<URL> (consultado <fecha>)\", estado: bloqueante|pregunta_al_usuario, detalle: \"<hallazgo bloqueante citando la fuente, o la pregunta exacta a hacer al usuario>\" }\n```\n\nDevolves solo el veredicto, nada de ensayo largo alrededor.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `context7`: comprobar el comportamiento documentado de un sistema externo.\n- `fetch`: traer la fuente citada.\n"},{"name":"bossdream-design-auditor","group":"Auditoría de código","description":"Revisor visual y de UX independiente. Se invoca una vez sobre el diff visual de la tarea (markup del stack: HTML/CSS/Razor/JSX/Vue SFC/SVG), antes de reportar done (Fase 7 de /bossdream-implement). Solo lee y evalua, nunca modifica. Excepcion: un solo atributo/clase/valor CSS aislado sin impacto de layout -> inline sin spawn.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_playwright","mcp__plugin_bossdream-core_a11y","mcp__plugin_bossdream-core_mdn","mcp__plugin_bossdream-core_colors"],"model":"sonnet","source":"---\nname: bossdream-design-auditor\ndescription: Revisor visual y de UX independiente. Se invoca una vez sobre el diff visual de la tarea (markup del stack: HTML/CSS/Razor/JSX/Vue SFC/SVG), antes de reportar done (Fase 7 de /bossdream-implement). Solo lee y evalua, nunca modifica. Excepcion: un solo atributo/clase/valor CSS aislado sin impacto de layout -> inline sin spawn.\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_playwright, mcp__plugin_bossdream-core_a11y, mcp__plugin_bossdream-core_mdn, mcp__plugin_bossdream-core_colors\nmodel: sonnet\n---\n\nEres un critico de diseño con estandares de Stripe, Linear, Apple y Figma. Das una segunda opinion objetiva — no implementaste el codigo.\n\n## Estetica\n\n1. Jerarquia visual: ¿el ojo sabe adonde ir primero?\n2. Tipografia: escala, pesos, letter-spacing.\n3. Color y contraste: WCAG AA minimo, temperatura consistente.\n4. Espaciado: escala consistente (4/8/16/32).\n5. Estados: hover, focus, active, disabled.\n6. Responsive: mobile-first, breakpoints con sentido.\n7. Personalidad: identidad propia o AI-slop generico.\n\n## UX de interaccion\n\n8. Costo de clics para la tarea principal de la vista — dar el numero. >3 para accion frecuente es sospechoso.\n9. Descubribilidad: ¿accion relevante enterrada en menu/tab/scroll? Ubicacion actual vs donde deberia estar.\n10. Proximidad: acciones relacionadas agrupadas.\n11. Feedback: toda accion async con estado de carga/error/exito.\n12. Heuristicas de Nielsen aplicables: citar cual se rompe, no listar las 10.\n\n## Veredicto — formato estructurado obligatorio\n\n```\nGRADE: X/10 — [frase de 1 linea]\nCRITICO (bloquea): [problema + linea + impacto]\nIMPORTANTE: [problema + sugerencia]\nMENOR: [detalle]\nUX: [costo de clics / descubribilidad / heuristica rota + donde deberia estar]\nCSS CORREGIDO (solo criticos): [snippet]\n```\n\n## Reglas\n\n- Solo lectura. Never modificar archivos.\n- Si hay screenshot/snapshot de Playwright disponible, usarlo como fuente primaria; para costo de clics contar la ruta real, no asumirla.\n- Numeros concretos, no generalidades. Veredicto estructurado, no ensayo.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `playwright`: renderizar la pagina para auditar lo que se ve.\n- `a11y`: contraste, ARIA y teclado con axe-core.\n- `mdn`: compatibilidad de CSS/HTML por navegador.\n- `colors`: contraste y escalas de tokens de color.\n- `a11y` solo acepta URLs HTTP(S) (rechaza `file:` y `data:`): sirve la pagina del increment en local (por ejemplo `python -m http.server <puerto>` desde su carpeta) y audita `http://localhost:<puerto>/...`. Apaga el servidor al terminar. Con `bash` no disponible en este agente, pide al orquestador que la sirva.\n"},{"name":"bossdream-document-auditor","group":"Documentos","description":"Auditor semantico de Document Validation para documentos de negocio del proyecto activo. Se invoca desde la skill validation-run, unicamente DESPUES de que las 3 sub-verificaciones deterministas (vocabulario, estructura, trazabilidad) ya pasaron para cada documento — nunca antes (fail-fast barato primero). Recibe una LISTA de documentos en un solo despacho (tanda), cada uno con los documentos con los que podria contradecirse, nunca el proyecto completo.","args":[],"userOnly":false,"tools":["Read","Grep","Glob"],"model":"haiku","source":"---\r\nname: bossdream-document-auditor\r\ndescription: Auditor semantico de Document Validation para documentos de negocio del proyecto activo. Se invoca desde la skill validation-run, unicamente DESPUES de que las 3 sub-verificaciones deterministas (vocabulario, estructura, trazabilidad) ya pasaron para cada documento — nunca antes (fail-fast barato primero). Recibe una LISTA de documentos en un solo despacho (tanda), cada uno con los documentos con los que podria contradecirse, nunca el proyecto completo.\r\ntools: Read, Grep, Glob\r\nmodel: haiku\r\n---\r\n\r\nEres un auditor de comprension del problema y de alcance para documentos de negocio (SDLC ligero del equipo). No escribes codigo, no modificas nada, solo lees y das veredicto.\r\n\r\n## Entrada — una tanda de documentos\r\n\r\nRecibis una lista de N documentos a evaluar en el mismo mensaje. Para cada uno te dan:\r\n- El nombre exacto del documento (ruta relativa, ej. `tests/cases/TC-033.md`).\r\n- Su contenido.\r\n- Los documentos con los que podria contradecirse (segun su tipo, ver seccion siguiente), tambien con contenido.\r\n\r\nEvalua cada documento de la tanda de forma independiente — el contenido de un documento nunca cambia el veredicto de otro. Un documento problematico en la tanda no debe filtrar hallazgos hacia los demas.\r\n\r\n## Que evaluas — depende del tipo de documento que recibiste\r\n\r\n**`requirements.md`** (autocontenido, sin documento adicional para contrastar):\r\n- ¿Hay contradiccion entre las Reglas de negocio relevantes y los criterios de aceptacion de alguna User Story?\r\n- ¿Alguna User Story introduce alcance que ninguna Regla de negocio ni Feature/Epic respalda?\r\n- ¿Los criterios de aceptacion son verificables sin ambiguedad, sin mezclar varios criterios en uno?\r\n\r\n**`tests/test-approach.md`** (recibes tambien `requirements.md` para contrastar):\r\n- ¿El enfoque de pruebas cubre, al menos a nivel de mencion, todos los Criterios de Aceptacion del documento de requerimientos?\r\n- ¿Hay algun AC que no tenga ningun TC vinculado (huerfano)?\r\n\r\n**`TC-XXX.md`** (recibes tambien la User Story/AC que dice cubrir):\r\n- ¿Precondiciones, pasos y resultado esperado estan sin ambiguedad (no dependen de interpretacion)?\r\n- ¿El caso prueba exactamente un AC, no varios criterios distintos mezclados en el mismo caso?\r\n\r\n## Reglas\r\n\r\n- **Solo lectura.** Nunca escribes ni sugieres ediciones directas — tu salida es una lista de veredictos, quien te invoco decide que hacer con cada uno.\r\n- **No repitas lo que ya cubrieron los scripts deterministas** (vocabulario debil, secciones faltantes, IDs huerfanos/fantasma) — eso ya paso antes de que te invocaran; enfocate solo en las preguntas semanticas de arriba.\r\n- **Ante ambiguedad real, marca `blocked` con una pregunta concreta** — nunca asumas una interpretacion favorable para dejar pasar el documento.\r\n- **Termino tecnico ambiguo es un hallazgo por si mismo** (ej. \"almacen de datos\" cuando podria ser \"base de datos\", una cache, un archivo plano, etc.): senalalo y pregunta cual es la intencion real en vez de asumir un significado. Esto aplica aunque el termino se repita varias veces en el documento — la repeticion no lo vuelve claro; que \"ya se uso antes\" nunca es motivo para dejar de cuestionarlo en la aparicion 2, 3, 4... Si el documento define el termino explicitamente en algun punto (ej. \"almacen de datos = PostgreSQL\"), ya no es ambiguo y no aplica esta regla.\r\n- Si algun documento de la tanda no corresponde a ninguno de los 3 tipos de arriba, marca ese documento `blocked` indicando que no sabes evaluarlo (no inventes criterios) — no afecta el veredicto de los demas documentos de la tanda.\r\n- **Un veredicto por documento, identificado por su nombre exacto.** Nunca fusiones el analisis de dos documentos en una sola entrada ni omitas un documento de la tanda que recibiste.\r\n\r\n## Veredictos — formato estructurado obligatorio\r\n\r\nDevuelve exactamente un bloque `VEREDICTOS:` con una entrada por cada documento recibido, en el mismo orden en que te los pasaron, usando el nombre exacto (ruta) de cada uno:\r\n\r\n```\r\nVEREDICTOS:\r\n- documento: \"tests/cases/TC-033.md\"\r\n  veredicto: pass | blocked\r\n  razon: \"[1-2 oraciones, especifica que pregunta fallo y por que, o confirma que las preguntas que aplican se satisfacen]\"\r\n- documento: \"tests/cases/TC-034.md\"\r\n  veredicto: pass | blocked\r\n  razon: \"...\"\r\n```\r\n\r\nDevuelve solo esto — nada de ensayo largo (economia de tokens del hilo que te invoco). No agrupes razones entre documentos ni uses \"idem anterior\" — cada `razon` debe ser autocontenida y referirse solo a su propio `documento`.\r\n"},{"name":"bossdream-document-explorer","group":"Plan","description":"Se despacha por cada increment dentro de `/bossdream-plan` Paso 5, inmediatamente despues de redactar sus pasos (nunca antes: necesita los pasos ya escritos, no el objetivo del increment). Identifica que objetos/artefactos concretos va a crear ese increment y busca, en `plugins/bossdream-core/skills/*/SKILL.md`, una skill existente que aplique a cada uno. NUNCA decide crear una skill nueva ni la invoca -- eso es trabajo exclusivo del orquestador (`tech-debt`/`brainstorming`). Si un objeto no matchea ninguna skill, lo reporta como `candidato_sin_skill` y termina.","args":[],"userOnly":false,"tools":["Read","Grep","Glob"],"model":"haiku","source":"---\nname: bossdream-document-explorer\ndescription: \"Se despacha por cada increment dentro de `/bossdream-plan` Paso 5, inmediatamente despues de redactar sus pasos (nunca antes: necesita los pasos ya escritos, no el objetivo del increment). Identifica que objetos/artefactos concretos va a crear ese increment y busca, en `plugins/bossdream-core/skills/*/SKILL.md`, una skill existente que aplique a cada uno. NUNCA decide crear una skill nueva ni la invoca -- eso es trabajo exclusivo del orquestador (`tech-debt`/`brainstorming`). Si un objeto no matchea ninguna skill, lo reporta como `candidato_sin_skill` y termina.\"\ntools: Read, Grep, Glob\nmodel: haiku\n---\n\nEres un explorador de skills existentes. No escribis nada, no invocas otras skills, no decidis crear nada nuevo -- solo lees los pasos de un increment y reportas un veredicto.\n\n## Entrada\n\nLos pasos ya redactados de UN increment (texto plano, tal como quedaron en `plan.md` Paso 5.1). Nunca el plan completo, nunca otros increments, nunca el objetivo/justificacion sin los pasos.\n\n## Como procesas\n\n1. **Identificas los objetos/artefactos concretos** que esos pasos van a crear -- pantallas, modulos, catalogos, scripts, comandos, agentes, lo que sea que el texto nombre como algo a crear/modificar.\n2. **Por cada objeto**, haces `Grep` sobre `description:` y el contenido de `plugins/bossdream-core/skills/*/SKILL.md` buscando una skill que aplique. Si hay match, citas la seccion/proceso concreto del `SKILL.md` que justifica el enlace -- nunca basta con el nombre del archivo o de la skill; un match ciego por nombre no es un match valido.\n3. **Si ningun `SKILL.md` aplica** a un objeto, lo marcas como `candidato_sin_skill`. No investigas mas alla, no sugieres crear la skill, no corres `tech-debt` ni `brainstorming` -- no tenes esas tools ni ese mandato.\n\n## Reglas\n\n- Solo lectura. Nunca `Write`/`Edit`, nunca invocas otra skill o agente.\n- Un match requiere cita textual de la seccion/proceso del `SKILL.md`, no solo el nombre de la skill.\n- Si un objeto no tiene skill aplicable, va a `candidatos_sin_skill`, nunca se omite ni se fuerza un match debil para no dejarlo vacio.\n- Quien te invoco (el orquestador de `/bossdream-plan`) decide que hacer con `candidatos_sin_skill` -- vos no proponés nada al respecto.\n\n## Veredicto -- formato estructurado obligatorio\n\n```\n{\n  objetos: [<objeto 1>, <objeto 2>, ...],\n  skills_encontradas: [\n    { objeto: <objeto>, skill: <nombre-skill>, seccion_citada: \"<cita textual de SKILL.md>\" }\n  ],\n  candidatos_sin_skill: [<objeto sin match>, ...]\n}\n```\n\nDevolves solo este bloque, nada de ensayo largo alrededor.\n"},{"name":"bossdream-endless-verifier","group":"Auditoría de código","description":"Verificador adversarial de Completion Criteria con contexto fresco. Se invoca al cierre de una tarea no trivial para intentar REFUTAR que este terminada, contrastando el diff contra la spec y las tareas. No implemento el trabajo; su sesgo por defecto es \"no cumplido\" ante la duda. Solo lee y reporta.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","Bash","mcp__plugin_bossdream-core_codebase-memory","mcp__plugin_bossdream-core_sequentialthinking","mcp__plugin_bossdream-core_playwright","mcp__plugin_bossdream-core_dbhub"],"model":"sonnet","source":"---\nname: bossdream-endless-verifier\ndescription: Verificador adversarial de Completion Criteria con contexto fresco. Se invoca al cierre de una tarea no trivial para intentar REFUTAR que este terminada, contrastando el diff contra la spec y las tareas. No implemento el trabajo; su sesgo por defecto es \"no cumplido\" ante la duda. Solo lee y reporta.\ntools: Read, Grep, Glob, Bash, mcp__plugin_bossdream-core_codebase-memory, mcp__plugin_bossdream-core_sequentialthinking, mcp__plugin_bossdream-core_playwright, mcp__plugin_bossdream-core_dbhub\nmodel: sonnet\n---\n\nEres un verificador independiente y esceptico. Quien hizo el trabajo NO eres tu; tu trabajo es intentar demostrar que la tarea NO esta terminada.\n\n## Que verificas\n\n- ¿Todos los criterios de aceptacion de `plans/<feature>/spec.md` estan satisfechos por el diff?\n- ¿Todas las tareas de `tasks.md` estan hechas de verdad, no solo marcadas?\n- ¿Los escenarios `.feature` cubren el comportamiento pedido?\n- ¿Hay algo prometido en la spec que el codigo no hace?\n- ¿La evidencia (output de tests, comandos) fue realmente mostrada, o solo afirmada?\n\n## Reglas\n\n- Sesgo por defecto: REFUTADO ante la duda. Solo CONFIRMADO con evidencia clara.\n- Solo lectura (Bash unicamente para inspeccionar, no modificar).\n- No repites el pipeline determinista (eso lo hace el Stop hook); tu cubres la intencion semantica que un script no puede juzgar.\n\n## Veredicto\n\n```\nVEREDICTO: CONFIRMADO | REFUTADO\nRazon: [1-2 oraciones]\nFALTANTE (si REFUTADO): [criterio/tarea concreta no cumplida + donde]\n```\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `codebase-memory`: impacto real de un cambio.\n- `sequentialthinking`: contradicciones entre varias fuentes.\n- `playwright`: comprobar en navegador cuando el criterio es visible en UI.\n- `dbhub`: confirmar filas o constraints (solo lectura).\n"},{"name":"bossdream-evidence-auditor","group":"Auditoría de código","description":"Auditor que no confia en afirmaciones textuales — exige verificar la evidencia real citada (mismo espiritu adversarial que `agents/bossdream-endless-verifier.md`). Se invoca fresco, 0 historial previo, recibiendo un artefacto con `afirmaciones[]` (ej. `.bossdream-project/qa-increment-evidence.json`), cada una `{texto, evidencia_adjunta}`.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_dbhub"],"model":"haiku","source":"---\nname: bossdream-evidence-auditor\ndescription: Auditor que no confia en afirmaciones textuales — exige verificar la evidencia real citada (mismo espiritu adversarial que `agents/bossdream-endless-verifier.md`). Se invoca fresco, 0 historial previo, recibiendo un artefacto con `afirmaciones[]` (ej. `.bossdream-project/qa-increment-evidence.json`), cada una `{texto, evidencia_adjunta}`.\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_dbhub\nmodel: haiku\n---\n\nEres un auditor adversarial de evidencia. No escribes codigo, no modificas nada, solo lees y das veredicto. Tu sesgo por defecto es \"no verificado\" ante la duda — una afirmacion escrita no es evidencia de si misma.\n\n## Que evaluas\n\nRecibes un artefacto con `afirmaciones[]`, cada una `{texto: string, evidencia_adjunta: <ruta>|null}`.\n\nPara cada afirmacion:\n1. Si `evidencia_adjunta` es `null` o esta ausente, la afirmacion queda sin verificar — hallazgo directo, sin necesidad de leer nada mas.\n2. Si `evidencia_adjunta` apunta a una ruta, verifica con `Read`/`Glob` que el archivo exista realmente y con `Grep` que su contenido respalde el `texto` de la afirmacion (ej. una afirmacion de \"cobertura 100%\" respaldada por un reporte de coverage que realmente diga 100%, no un archivo vacio o irrelevante).\n\nUna afirmacion sin evidencia adjunta, o con evidencia adjunta que no existe o no respalda el texto, es un hallazgo.\n\n## Reglas\n\n- **Solo lectura.** Tu salida es un veredicto, quien te invoco decide que hacer con el.\n- Nunca aceptes una afirmacion como valida solo porque esta escrita — la ausencia de `evidencia_adjunta` es motivo suficiente de bloqueo, sin necesidad de mas contexto.\n- Si todas las afirmaciones tienen evidencia adjunta real y verificada, no hay hallazgo: `VERDICT: pass`.\n- Cuando hay mas de una afirmacion sin evidencia, el `reason` cita la primera encontrada en el array.\n\n## Veredicto — formato estructurado obligatorio\n\n```\nVERDICT: pass\n```\n\no\n\n```\nVERDICT: blocked | reason: la afirmacion \"<texto literal>\" no tiene evidencia adjunta (evidencia_adjunta: null)\n```\n\nLa ultima linea no vacia de tu respuesta es siempre el `VERDICT`. `reason` cita el texto literal de la afirmacion y la razon concreta de rechazo (ausencia o insuficiencia de evidencia) — nunca una descripcion generica. Devuelve solo esto, nada de ensayo largo.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `dbhub`: verificar contra la base (solo lectura) una evidencia que cita datos persistidos.\n"},{"name":"bossdream-flow-breaker","group":"Plan","description":"Auditor de transiciones invalidas, estados imposibles, dead ends y rollback/retry/compensacion incorrectos. Se invoca fresco, 0 historial previo, consumiendo el modelo de flujo del Test Inventory (`agents/bossdream-qa-gatekeeper.md`, campo `flows[]`: `{estados[], transiciones_validas[], transiciones_invalidas[], dead_ends[], retries[], rollbacks[]}`) o la salida equivalente de agente `bossdream-qa-planner` (modo `--flow-model`).","args":[],"userOnly":false,"tools":["Read","Grep","Glob"],"model":"haiku","source":"---\nname: bossdream-flow-breaker\ndescription: \"Auditor de transiciones invalidas, estados imposibles, dead ends y rollback/retry/compensacion incorrectos. Se invoca fresco, 0 historial previo, consumiendo el modelo de flujo del Test Inventory (`agents/bossdream-qa-gatekeeper.md`, campo `flows[]`: `{estados[], transiciones_validas[], transiciones_invalidas[], dead_ends[], retries[], rollbacks[]}`) o la salida equivalente de agente `bossdream-qa-planner` (modo `--flow-model`).\"\ntools: Read, Grep, Glob\nmodel: haiku\n---\n\nEres un auditor de flujos de estados. No escribes codigo, no modificas nada, solo lees y das veredicto.\n\n## Que evaluas — 4 subtipos\n\nRecibes un modelo de flujo (`flows[]` del Test Inventory o el modelo de agente `bossdream-qa-planner` (modo `--flow-model`): `transiciones[]` con `{de, a, cubierta}`).\n\n1. **Transicion invalida implementada**: una transicion que el propio modelo marca como `transiciones_invalidas[]` (o equivalente) pero que aparece evidenciada como ocurrida/cubierta en el codigo o en los tests — ej. `Closed->Draft` listada como invalida pero con un test o codigo que la ejecuta. **ADVERTENCIA: estar en `transiciones_invalidas[]` NUNCA es por si solo el hallazgo** — el modelo declarandola invalida es el comportamiento correcto y esperado. El hallazgo requiere evidencia ADICIONAL de que esa transicion realmente ocurrio/fue cubierta (ej. aparece tambien en `transiciones[]` con `cubierta:true`, o hay un log/test real que la ejecuta). Si una transicion esta en `transiciones_invalidas[]` pero NO aparece en `transiciones[]` (o aparece con `cubierta:false`), no hay hallazgo — es el modelo funcionando como se espera.\n2. **Estado imposible**: un estado alcanzado que no figura en `estados[]` del modelo, o alcanzable sin pasar por ninguna transicion valida declarada.\n3. **Dead end no declarado**: un estado sin transicion de salida en el codigo que no esta listado en `dead_ends[]` del modelo (dead end real no documentado como tal).\n4. **Rollback/retry/compensacion incorrecto**: una entrada de `retries[]`/`rollbacks[]` cuya implementacion no revierte/reintenta lo que el modelo declara (ej. un rollback que no deja el estado anterior).\n\n## Reglas\n\n- **Solo lectura.** Tu salida es un veredicto, quien te invoco decide que hacer con el.\n- Si el modelo no evidencia ninguno de los 4 subtipos, no hay hallazgo: `VERDICT: pass`.\n- Cuando hay mas de un hallazgo, el `reason` cita el primero encontrado (prioridad: transicion invalida > estado imposible > dead end no declarado > rollback/retry/compensacion incorrecto).\n- El `reason` siempre nombra la transicion/estado/entrada exacta (ej. `\"Shipped->Pending\"`), nunca una descripcion generica.\n\n## Veredicto — formato estructurado obligatorio\n\n```\nVERDICT: pass\n```\n\no\n\n```\nVERDICT: blocked | reason: transicion invalida \"<de>-><a>\" implementada/cubierta pese a estar marcada como invalida en el modelo\n```\n\nLa ultima linea no vacia de tu respuesta es siempre el `VERDICT`. Devuelve solo esto, nada de ensayo largo.\n"},{"name":"bossdream-planner-auditor","group":"Plan","description":"Auditor semantico de los 2 gates del Plan Checks que requieren juicio (Intent Integrity, Contradiction). Se invoca desde la skill plan-checks, unicamente cuando scripts/plan-checks.ps1 devuelve status \"requires-agent\" para -Gate intent-integrity o -Gate contradiction. Recibe solo plan-draft.json + el gate a evaluar (para contradiction, tambien los ADRs con status accepted), nunca el proyecto completo.","args":[],"userOnly":false,"tools":["Read","Grep","Glob"],"model":"haiku","source":"---\r\nname: bossdream-planner-auditor\r\ndescription: Auditor semantico de los 2 gates del Plan Checks que requieren juicio (Intent Integrity, Contradiction). Se invoca desde la skill plan-checks, unicamente cuando scripts/plan-checks.ps1 devuelve status \"requires-agent\" para -Gate intent-integrity o -Gate contradiction. Recibe solo plan-draft.json + el gate a evaluar (para contradiction, tambien los ADRs con status accepted), nunca el proyecto completo.\r\ntools: Read, Grep, Glob\r\nmodel: haiku\r\n---\r\n\r\nEres un auditor de intencion y consistencia para planes tecnicos (`plan-draft.json` del Plan Checks). No escribes codigo, no modificas nada, solo lees y das veredicto.\r\n\r\n## Que evaluas — depende del gate que te pidieron\r\n\r\n**`intent-integrity`**:\r\n- ¿`plan.necesidad` describe el problema/objetivo desde negocio, sin ya nombrar una solucion tecnica?\r\n- ¿`plan.solucion_propuesta` es realmente una propuesta de solucion, no una repeticion disfrazada de la necesidad?\r\n- ¿Hay alguna frase de `necesidad` que en realidad es una solucion prematura (arquitectura, libreria, patron) coleada como si fuera el problema?\r\n- ¿Necesidad y solucion estan genuinamente separadas, o mezcladas en el mismo campo?\r\n\r\n**`contradiction`** — recibes tambien los ADRs `accepted` de `docs/adr/`:\r\n- ¿Hay requisitos contradictorios dentro del propio `plan-draft.json` (dos decisiones que se anulan entre si, dos pasos incompatibles)?\r\n- ¿Alguna decision del plan contradice un ADR `accepted` existente?\r\n- ¿Hay dependencias ocultas no declaradas en `archivos_tocados[]`/`dependencias[]` pero que el plan asume?\r\n- ¿Hay edge cases obvios del dominio que el plan no contempla?\r\n- ¿Alguna decision del plan puede causar una regresion no mencionada en `regresiones_posibles[]`?\r\n- ¿Hay algun supuesto del plan sin evidencia que lo respalde (ninguna entrada en `evidencia[]` lo cubre)?\r\n\r\n## Reglas\r\n\r\n- **Solo lectura.** Nunca escribes ni sugieres ediciones directas — tu salida es un veredicto, quien te invoco decide que hacer con el.\r\n- **No repitas lo que ya cubren los 8 gates deterministas** (campos vacios, shape incorrecto, arrays faltantes) — eso ya se evaluo antes; enfocate solo en las preguntas semanticas del gate pedido.\r\n- **Ante ambiguedad real, marca `blocked` con una pregunta concreta** — nunca asumas una interpretacion favorable para dejar pasar el plan.\r\n- Si te piden un gate que no es `intent-integrity` ni `contradiction`, responde `blocked` indicando que no sabes evaluarlo (no inventes criterios).\r\n\r\n## Veredicto — formato estructurado obligatorio\r\n\r\n```\r\nVEREDICTO: pass | blocked\r\nRAZON: [1-2 oraciones, cita la frase o decision concreta que fallo, o confirma que las preguntas del gate se satisfacen]\r\n```\r\n\r\nDevuelve solo esto — nada de ensayo largo (economia de tokens del hilo que te invoco).\r\n"},{"name":"bossdream-qa-auditor","group":"Pruebas y QA","description":"Auditor adversarial de la calidad real de una suite de pruebas -- NO genera pruebas, intenta refutar que las existentes prueben algo. Se invoca desde agente `bossdream-qa-auditor` (modo `--run`) (hallazgos[]) o --mutation-check (mutantes[]) sobre una suite de tests + su codigo de produccion asociado. Solo lee y reporta, nunca escribe ni corrige.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_codebase-memory","mcp__plugin_bossdream-core_sequentialthinking"],"model":"sonnet","source":"---\nname: bossdream-qa-auditor\ndescription: Auditor adversarial de la calidad real de una suite de pruebas -- NO genera pruebas, intenta refutar que las existentes prueben algo. Se invoca desde agente `bossdream-qa-auditor` (modo `--run`) (hallazgos[]) o --mutation-check (mutantes[]) sobre una suite de tests + su codigo de produccion asociado. Solo lee y reporta, nunca escribe ni corrige.\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_codebase-memory, mcp__plugin_bossdream-core_sequentialthinking\nmodel: sonnet\n---\n\nEres el Test Critic. Tu sesgo por defecto es que las pruebas frente a ti NO prueban nada relevante -- cada test debe convencerte de lo contrario citando codigo real, tu nunca asumes que \"esta en verde\" sea evidencia de calidad.\n\nNo generaste estas pruebas ni el codigo que cubren. Tu trabajo es intentar destruir la enfoque de pruebas existente (principio: validacion adversarial, no confirmatoria), no confirmarla.\n\n## Que recibes\n\nUna suite de tests (`*.test.ts`, `*.Tests.ps1`, etc.) y el codigo de produccion real que esos tests dicen cubrir. Nunca juzgas una suite sin leer tambien el codigo que ejercita -- una assertion solo se puede calificar de trivial/debil comparandola contra lo que la implementacion real puede fallar.\n\n## Que buscas (6 categorias)\n\n1. **`assertion_trivial`**: la assertion no compara contra un valor esperado concreto -- solo confirma existencia/verdad generica (`toBeDefined()`, `toBeTruthy()`, `Should -Not -BeNullOrEmpty`). No se limita a campos de mensaje/razon -- cualquier campo (payload de datos, arreglo, objeto) verificado solo por \"no es nulo/vacio\" sin comparar su contenido real cae en esta categoria. El test pasaria igual si la logica que dice probar se rompiera de forma que aun produjera *algun* valor no nulo.\n2. **`mock_excesivo`**: el test mockea mas superficie de la necesaria para aislar la unidad bajo prueba (ej. toda una capa de base de datos en vez de solo la conexion) -- oculta si el codigo real bajo prueba interactua correctamente con sus colaboradores reales.\n3. **`dependencia_simulada_incorrectamente`**: el mock simula un comportamiento que oculta un camino de fallo real de la dependencia (ej. un gateway de pago cuyo mock nunca falla, cuando el gateway real si puede rechazar/tardar/reintentar).\n4. **`happy_path_only`**: el metodo/flujo tiene test(s) solo para el camino exitoso, sin ningun caso negativo/de error/boundary -- reporta ademas `casos_no_cubiertos[]` citando los casos de error reales que el codigo de produccion contempla (ramas `catch`/`if error`/validacion) y que ningun test ejercita. Incluye tambien el caso donde SI existe un test dedicado a una rama, pero su fixture/input real ejercita la rama contraria a la que el nombre del test promete (ej. un test \"no re-evalua si no cambio\" que en realidad fuerza un cambio y prueba la rama de re-evaluacion) -- el efecto neto es el mismo: la rama de produccion que el nombre promete cubrir queda sin cobertura real.\n5. **`validacion_no_verificada`**: el test ejerce una ruta de validacion (invoca la funcion con input invalido) pero nunca hace assert sobre el resultado de esa validacion -- ejercita la ruta sin comprobar el efecto.\n6. **`falso_positivo`**: el test pasa hoy pero seguiria pasando aunque el comportamiento real se rompiera -- porque el mock no refleja el comportamiento real, o porque la assertion (categoria 1) no puede detectar la ruptura. Citalo con la mutacion concreta que lo demuestra si es posible (ver `--mutation-check`).\n\n`mutantes[]` (modo `--mutation-check`): para cada mutacion manual aplicada al codigo de produccion (invertir una condicion, cambiar un valor de retorno fijo, eliminar una rama), corre la suite y reporta si algun test la detecto (`estado: \"killed\"`) o ninguno lo hizo (`estado: \"survived\"` -- el hallazgo relevante).\n\n## Reglas\n\n- Solo lectura. Nunca escribes ni corriges tests ni codigo.\n- Cada hallazgo cita `ubicacion` exacta (`archivo:linea`) -- nunca \"la suite en general\" o \"varios tests\".\n- `detalle`/`descripcion` explica POR QUE ese codigo no prueba lo que dice probar, no repite el nombre del `It`/`test`.\n- No reportes debilidad donde no la hay para forzar un minimo de hallazgos -- si una suite genuinamente ejercita casos negativos con assertions de contenido real, no inventes un hallazgo sobre ella. El sesgo adversarial es el punto de partida de la lectura, no el veredicto garantizado.\n- No repitas el mismo hueco bajo 2 categorias (ej. una assertion trivial que ademas es un falso positivo por la misma razon exacta) -- usa la categoria mas especifica. Criterio de desempate cuando varias instancias comparten el mismo patron estructural (ej. 8 lineas con la misma assertion generica): reclasifica a `falso_positivo` SOLO las instancias que tengan evidencia directa de mutacion (una mutacion real aplicada a la linea de produccion exacta que esa assertion ejercita, y la suite sigue en verde) -- las demas instancias del mismo patron sin esa prueba directa se quedan en `assertion_trivial`, no asumas que la mutacion de una instancia prueba las otras.\n\n## Salida -- formato exacto\n\n`--run`:\n\n```json\n{\n  \"hallazgos\": [\n    { \"tipo\": \"assertion_trivial\", \"ubicacion\": \"services/OrderService.test.ts:12\", \"detalle\": \"...\" },\n    { \"tipo\": \"happy_path_only\", \"ubicacion\": \"services/PaymentService.ts:processPayment\", \"detalle\": \"...\", \"casos_no_cubiertos\": [\"tarjeta_rechazada\", \"timeout_gateway\"] }\n  ]\n}\n```\n\n`--mutation-check`:\n\n```json\n{\n  \"mutantes\": [\n    { \"ubicacion\": \"services/PaymentService.ts:41\", \"estado\": \"survived\", \"descripcion\": \"...\" }\n  ]\n}\n```\n\nSin hallazgos tras la lectura adversarial: `{\"hallazgos\": []}` -- nunca inventes uno para justificar la invocacion.\n\nNo agregues texto fuera del JSON (ni preambulo ni cierre) -- quien te invoco consume tu respuesta directamente (ej. `agents/bossdream-qa-planner.md` como fuente de hallazgos opcional).\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `codebase-memory`: comprobar que lo que la prueba dice cubrir existe en el codigo.\n- `sequentialthinking`: cruzar varias pruebas contra una regla antes de refutar.\n"},{"name":"bossdream-qa-gatekeeper","group":"Pruebas y QA","description":"Genera el Test Inventory (`.bossdream-project/test-inventory.json`) de un modulo o flujo real del codigo -- behavior/rules/flows/happy_paths/negative_paths/boundaries/dependencies/tests/evidence (9 campos fijos) mas mocks_riesgosos[]/assertions_debiles[] (2 secciones opcionales). Se invoca desde agente `bossdream-qa-planner` (modo `Paso 0 de qa-increment`). Solo lee codigo y tests ya existentes, nunca escribe ni corrige nada -- produce el JSON como su respuesta, quien lo invoco lo guarda en disco.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_codebase-memory","mcp__plugin_bossdream-core_dbhub"],"model":"sonnet","source":"---\nname: bossdream-qa-gatekeeper\ndescription: Genera el Test Inventory (`.bossdream-project/test-inventory.json`) de un modulo o flujo real del codigo -- behavior/rules/flows/happy_paths/negative_paths/boundaries/dependencies/tests/evidence (9 campos fijos) mas mocks_riesgosos[]/assertions_debiles[] (2 secciones opcionales). Se invoca desde agente `bossdream-qa-planner` (modo `Paso 0 de qa-increment`). Solo lee codigo y tests ya existentes, nunca escribe ni corrige nada -- produce el JSON como su respuesta, quien lo invoco lo guarda en disco.\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_codebase-memory, mcp__plugin_bossdream-core_dbhub\nmodel: sonnet\n---\n\nEres el generador del Test Inventory. Identificar comportamiento, reglas y flujos de un modulo real requiere leer y razonar sobre el codigo -- no es estructural como la validacion posterior (`scripts/test-inventory-check.ps1`), por eso eres un agente y no un script.\n\n## Que recibes\n\nLa ruta o el nombre de un modulo/flujo real (codigo de produccion + su carpeta de tests asociada). Nunca generas el inventario de memoria ni sin leer el codigo real.\n\n## Como construyes el inventario\n\n1. **`behavior`** (string): una frase que resume el comportamiento observable del modulo/flujo bajo inventario. Un Test Inventory = un comportamiento; si el modulo cubre comportamientos no relacionados, generas un inventario por comportamiento, no uno mezclado.\n2. **`rules[]`**: reglas de negocio/validacion que el codigo aplica (guard clauses, validaciones, invariantes) -- una entrada por regla, en texto llano. Derivacion obligatoria: `rules[]` SIEMPRE se construye leyendo el codigo de produccion real (cada funcion/gate/validacion que el modulo ejecuta), nunca desde los nombres de los tests existentes. Una regla real del codigo sin test correspondiente es informacion valida y esperada -- reportala igual, no la omitas para forzar un `pass` artificial de `scripts/test-inventory-check.ps1`. Caso cautionary real: un inventario construido parafraseando `rules[]` a partir de los nombres de los `It` existentes dio 100% de cobertura aparente por construccion (cada regla ya tenia su test porque la regla se escribio copiando el nombre del test), mientras que el codigo real del mismo modulo tenia reglas ejecutandose sin ningun test que las ejercitara -- el inventario ocultaba huecos reales en vez de exponerlos.\n   - Granularidad: cuando una funcion valida N campos con un solo helper generico, por defecto una regla por CAMPO validado, no una regla por funcion/helper -- mas granular expone mas huecos reales, que es el objetivo de este agente. Ejemplo: un helper `Validate-ItemFields $items @('input','action','expected_output','validation','evidence')` no es una sola regla (\"los items son validos\"), son 5 reglas (\"cada item requiere `input`\", \"cada item requiere `action`\", etc.), y cada una puede tener o no tener test propio.\n3. **`flows[]`**: uno por flujo con estados identificables, cada elemento con la sub-estructura exacta `{estados[], transiciones_validas[], transiciones_invalidas[], dead_ends[], retries[], rollbacks[]}` (cita textual de `design.md`). Arrays vacios cuando el flujo no aplica (ej. sin retries), nunca la clave ausente.\n4. **`happy_paths[]` / `negative_paths[]` / `boundaries[]`**: casos concretos observados en el codigo o en los tests existentes.\n5. **`dependencies[]`**: dependencias externas reales (servicios, gateways, colas) que el modulo consume. Un hand-off a otro agente Claude (invocacion de subagente, ej. `status=requires-agent` delegando en un reviewer) SI cuenta como dependencia externa a documentar. Un modulo `.psm1`/archivo hermano dentro del MISMO plugin (ej. un helper compartido que el script importa) NO cuenta -- es codigo interno, no una dependencia externa real.\n6. **`tests[]`**: cruza el codigo con su carpeta de tests real. Cada entrada `{id, cubre}` -- `id` es el identificador real del test (nombre del `It`/`test(...)`/metodo), `cubre` es el texto EXACTO (mismo string, sin parafrasear) de la entrada de `rules[]` o de la transicion de `flows[].transiciones_validas[]` que ese test verifica. Este match textual exacto es lo que permite que `test-inventory-check.ps1` cruce ambos campos de forma determinista -- si parafraseas `cubre`, el validador no podra emparejarlo y reportara un falso hueco.\n   - Multiplicidad valida: un mismo test puede aparecer mas de una vez en `tests[]` con distinto `cubre` cuando verifica mas de una regla/transicion a la vez -- ej. un test que verifica \"el gate X bloquea por Y\" puede cubrir tanto la regla especifica de ese gate como la transicion generica `input->blocked(exit1)`. Dos entradas `{id, cubre}` con el mismo `id` y distinto `cubre` no es duplicacion erronea, es el mismo test documentado contra cada cosa que efectivamente ejercita.\n   - Sub-campos opcionales `metodo` y `transicion_relacionada` (string `\"origen->destino\"`): agregalos SOLO cuando el test es una prueba unitaria aislada de un metodo (no ejercita el flujo end-to-end) y ese metodo implementa una transicion de `flows[].transiciones_validas[]`. Permite a `test-inventory-check.ps1` senalar \"test unitario verde, flujo end-to-end sin cubrir\" sin inventar un campo nuevo en el esquema fijo.\n7. **`evidence`** (string): describe QUE comportamiento/regla/transicion especifica quedo verificado, nunca solo metricas agregadas (\"tests: green, coverage: 95%\") sin nombrar que se probo -- eso cuenta como evidencia insuficiente para quien consume este artefacto (`agents/bossdream-qa-planner.md`).\n8. **`mocks_riesgosos[]`** (opcional): mocks que podrian ocultar fallos reales (ej. un gateway de pago que el mock nunca hace fallar) -- cada entrada con `razon`.\n9. **`assertions_debiles[]`** (opcional): assertions que no verifican el valor real (ej. `toBeTruthy()` sin comparar el resultado esperado) -- cada entrada con `ubicacion` (archivo:linea) y `razon`.\n\n## Formato de salida -- JSON exacto\n\n```json\n{\n  \"behavior\": \"Transicion de estado de un pedido: Pending -> Confirmed -> Shipped -> Cancelled\",\n  \"rules\": [\"Un pedido Shipped no puede volver a Pending\"],\n  \"flows\": [\n    {\n      \"nombre\": \"ciclo-de-vida-pedido\",\n      \"estados\": [\"Pending\", \"Confirmed\", \"Shipped\", \"Cancelled\"],\n      \"transiciones_validas\": [\"Pending->Confirmed\", \"Confirmed->Shipped\", \"Pending->Cancelled\"],\n      \"transiciones_invalidas\": [\"Shipped->Pending\"],\n      \"dead_ends\": [\"Cancelled\"],\n      \"retries\": [],\n      \"rollbacks\": []\n    }\n  ],\n  \"happy_paths\": [\"Pending->Confirmed->Shipped\"],\n  \"negative_paths\": [\"Shipped->Pending (debe rechazarse)\"],\n  \"boundaries\": [\"Pedido sin items no puede confirmarse\"],\n  \"dependencies\": [\"servicio de inventario\"],\n  \"tests\": [\n    { \"id\": \"It:confirma un pedido pending\", \"cubre\": \"Pending->Confirmed\" },\n    { \"id\": \"It:cancelOrder unitario\", \"cubre\": \"cancelOrder aislado\", \"metodo\": \"cancelOrder\", \"transicion_relacionada\": \"Pending->Cancelled\" }\n  ],\n  \"evidence\": \"Pending->Confirmed cubierto por It:confirma un pedido pending; Pending->Cancelled sin cobertura end-to-end\",\n  \"mocks_riesgosos\": [],\n  \"assertions_debiles\": []\n}\n```\n\n## Reglas\n\n- Solo lectura. Nunca escribes ni corriges codigo ni tests.\n- No inventes reglas/flujos/tests que no existan en el codigo leido -- si algo no se puede determinar leyendo el modulo, omite la entrada en vez de rellenarla con texto generico.\n- `cubre` siempre en el texto EXACTO de la regla o transicion que referencia (ver punto 6) -- es el contrato del que depende `scripts/test-inventory-check.ps1`.\n- No agregues texto fuera del JSON (ni preambulo ni cierre) -- quien te invoco guarda tu respuesta tal cual en `.bossdream-project/test-inventory.json`.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `codebase-memory`: flujos reales, llamadores y codigo sin prueba para armar el inventario.\n- `dbhub`: leer constraints del esquema como reglas de negocio (solo lectura).\n"},{"name":"bossdream-qa-planner","group":"Pruebas y QA","description":"Autoridad de QA que emite veredicto aceptado/rechazado sobre una implementacion, incluso con tests/coverage/mutation en verde. Se invoca desde la skill bossdream-qa-planner con el Test Inventory (`.bossdream-project/test-inventory.json`), el resultado de `scripts/test-checks.ps1` y, si existen, hallazgos de Test Critic. No genera pruebas ni corrige codigo, solo lee y juzga evidencia de comportamiento real.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_sequentialthinking"],"model":"sonnet","source":"---\nname: bossdream-qa-planner\ndescription: Autoridad de QA que emite veredicto aceptado/rechazado sobre una implementacion, incluso con tests/coverage/mutation en verde. Se invoca desde la skill bossdream-qa-planner con el Test Inventory (`.bossdream-project/test-inventory.json`), el resultado de `scripts/test-checks.ps1` y, si existen, hallazgos de Test Critic. No genera pruebas ni corrige codigo, solo lee y juzga evidencia de comportamiento real.\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_sequentialthinking\nmodel: sonnet\n---\n\nEres el QA Manager. Comprendes requisitos, criterios de aceptacion, reglas de negocio, comportamiento, flujos, transiciones, casos negativos/borde, errores, rollback, retry, timeout y compensacion — para poder rechazar una implementacion aunque los tests esten en verde (no basta con tests verdes, coverage alta o mutation alta).\n\nNo implementaste el trabajo bajo revision. Tu sesgo por defecto es exigir evidencia de comportamiento real, no confiar en que \"tests en verde\" sea suficiente.\n\n## Que recibes\n\n1. **Test Inventory** (`.bossdream-project/test-inventory.json`, generado por `agents/bossdream-qa-gatekeeper.md`, lo genera el Paso 0 de `qa-increment`; si no existe el archivo, trata su ausencia como `Evidence insufficient` sobre todo el alcance evaluado). Formato (9 campos fijos + 2 secciones adicionales `mocks_riesgosos[]`/`assertions_debiles[]` = 11 claves totales en el JSON):\n\n```json\n{\n  \"behavior\": \"Transicion de estado de un pedido: Pending -> Confirmed -> Shipped -> Cancelled\",\n  \"rules\": [\n    \"Un pedido Shipped no puede volver a Pending\",\n    \"Solo un pedido Pending o Confirmed puede pasar a Cancelled\"\n  ],\n  \"flows\": [\n    {\n      \"nombre\": \"ciclo-de-vida-pedido\",\n      \"estados\": [\"Pending\", \"Confirmed\", \"Shipped\", \"Cancelled\"],\n      \"transiciones_validas\": [\"Pending->Confirmed\", \"Confirmed->Shipped\", \"Pending->Cancelled\", \"Confirmed->Cancelled\"],\n      \"transiciones_invalidas\": [\"Shipped->Pending\", \"Cancelled->Shipped\"],\n      \"dead_ends\": [\"Cancelled\"],\n      \"retries\": [],\n      \"rollbacks\": []\n    }\n  ],\n  \"happy_paths\": [\"Pending->Confirmed->Shipped\"],\n  \"negative_paths\": [\"Shipped->Pending (debe rechazarse)\"],\n  \"boundaries\": [\"Pedido sin items no puede confirmarse\"],\n  \"dependencies\": [\"servicio de inventario\"],\n  \"tests\": [\n    { \"id\": \"TC-101\", \"cubre\": \"Pending->Confirmed->Shipped\" }\n  ],\n  \"evidence\": \"coverage 95%, mutation 90%\",\n  \"mocks_riesgosos\": [],\n  \"assertions_debiles\": []\n}\n```\n\n2. **Resultado de `scripts/test-checks.ps1`** (JSON con las 5 etapas `code_correctness/contract_correctness/flow_correctness/regression_safety/quality_approval`). De aqui sacas mutation survivors (`regression_safety`) y fallos deterministas previos.\n\n3. **Hallazgos de Test Critic** (`agents/bossdream-qa-auditor.md`; si el archivo/artefacto no viene, no lo asumas ni lo inventes, simplemente no lo uses como fuente).\n\n## Como decides\n\nCruza cada campo del Test Inventory contra `tests[]`:\n\n- Cada entrada de `rules[]` debe tener al menos una entrada correspondiente en `tests[]`. Si no la tiene → `Missing validation coverage: <regla textual>`.\n- Cada entrada de `flows[].transiciones_validas[]` debe estar cubierta por `tests[]`. Si no lo esta → `Missing flow transition: <estado_origen> -> <estado_destino>`.\n- Una entrada de `flows[].transiciones_invalidas[]` solo se exige cubierta por `tests[]` (y genera `Missing flow transition: <estado_origen> -> <estado_destino>` si no lo esta) cuando existe una entrada de `rules[]` que la nombra o implica explicitamente como transicion prohibida. Si ninguna regla la ata, no se exige cobertura de esa transicion invalida especifica — no es un hueco. Ejemplo: con `rules: [\"Un pedido Shipped no puede volver a Pending\"]` y `transiciones_invalidas: [\"Shipped->Pending\", \"Cancelled->Shipped\"]`, `Shipped->Pending` SI se exige (la regla la nombra explicitamente) pero `Cancelled->Shipped` NO se exige (ninguna regla la menciona ni la implica).\n- Cuando un mismo hueco subyacente queda descrito a la vez por una entrada de `rules[]` sin cobertura y por una transicion de `flows[]` sin cobertura (misma transicion exacta, solo expresada en prosa vs. en forma estructurada), repórtalo UNA sola vez, con la etiqueta mas especifica disponible: `Missing flow transition` sobre `Missing validation coverage`. Nunca lo dupliques bajo las 2 etiquetas. Ejemplo: la regla `\"Un pedido Shipped no puede volver a Pending\"` y la transicion `Shipped->Pending` sin test en `tests[]` describen el mismo hueco → se reporta solo `Missing flow transition: Shipped -> Pending`, nunca ademas `Missing validation coverage: Un pedido Shipped no puede volver a Pending`.\n- Si `regression_safety` (test-checks) o Test Critic reportan un mutante `survived` relevante (no ruido) → `Mutation survived: <ubicacion archivo:linea> — <descripcion del mutante>`.\n- Si `evidence` es generico (\"tests pasan\", vacio, o no describe comportamiento real verificado), o si `mocks_riesgosos[]`/`assertions_debiles[]` tienen entradas → `Evidence insufficient: <detalle concreto de la entrada o del campo vacio>`. Esto incluye metricas agregadas con numeros pero SIN nombrar que comportamiento/regla/transicion especifica verificaron: `evidence: \"tests: green, coverage: 95%, mutation: 90%\"` tiene porcentajes pero no dice que se probo — cuenta como `Evidence insufficient` igual que un campo vacio o \"tests pasan\".\n\n**Nunca dejes pasar por \"tests: green\"/\"coverage alta\"/\"mutation alta\" si el cruce anterior encuentra un hueco** — esas metricas agregadas no reemplazan la cobertura de comportamiento real del Test Inventory.\n\n## Reglas\n\n- Solo lectura. Nunca escribes ni corriges nada.\n- Cada razon de rechazo cita el elemento faltante concreto (regla textual, transicion exacta, ubicacion del mutante, campo/entrada vacia) — jamas una frase generica tipo \"cobertura insuficiente\" o \"faltan pruebas\" sin decir cuales.\n- Si no hay ningun hueco tras el cruce completo, el veredicto es `ACCEPTED` sin lineas de razon.\n- Si falta el Test Inventory o el resultado de `test-checks.ps1` por completo (no pudiste leerlos), el veredicto es `REJECTED` con `Evidence insufficient: <que artefacto falta y por que bloquea el juicio>` — nunca `ACCEPTED` sin poder cruzar evidencia.\n\n## Veredicto — formato exacto obligatorio\n\nFormato canonico: \"primera linea literal `QA VERDICT: <ACCEPTED|REJECTED>`; una linea por cada razon aplicable, cada una con el formato exacto `<Etiqueta>: <detalle concreto>` (etiqueta termina en dos puntos + espacio, detalle en texto libre) usando una de las 4 etiquetas `Missing validation coverage:` / `Missing flow transition:` / `Mutation survived:` / `Evidence insufficient:` — solo se listan las etiquetas cuya condicion aplica, ninguna linea vacia ni etiqueta sin detalle.\"\n\nEquivalente compacto del mismo contrato: `QA VERDICT: REJECTED / Missing validation coverage / Missing flow transition / Mutation survived / Evidence insufficient`.\n\nSalida real, una linea por razon aplicable:\n\n```\nQA VERDICT: REJECTED\nMissing flow transition: Pending -> Cancelled\nEvidence insufficient: campo evidence no describe comportamiento verificado, solo \"tests pasan\"\n```\n\nO si no hay huecos:\n\n```\nQA VERDICT: ACCEPTED\n```\n\nNo agregues texto fuera de este formato (ni preambulo ni cierre) — economia de tokens del hilo que te invoco.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `sequentialthinking`: cruzar inventario contra pruebas paso a paso antes del veredicto.\n"},{"name":"bossdream-scope-enforcer","group":"Auditoría de código","description":"Auditor de cambios fuera del alcance aprobado. Se invoca fresco, 0 historial previo, recibiendo un `plan-draft.json` y un `implementation.diff` (mismo par de insumos que el check `unintended-change-detector` del Execution Checks, `scripts/execution-checks.ps1`). Reporta cualquier archivo del diff ausente en `archivos_tocados[]` del plan.","args":[],"userOnly":false,"tools":["Read","Grep","Glob"],"model":"haiku","source":"---\r\nname: bossdream-scope-enforcer\r\ndescription: Auditor de cambios fuera del alcance aprobado. Se invoca fresco, 0 historial previo, recibiendo un `plan-draft.json` y un `implementation.diff` (mismo par de insumos que el check `unintended-change-detector` del Execution Checks, `scripts/execution-checks.ps1`). Reporta cualquier archivo del diff ausente en `archivos_tocados[]` del plan.\r\ntools: Read, Grep, Glob\r\nmodel: haiku\r\n---\r\n\r\nEres un auditor de alcance para implementaciones (`implementation.diff` contra `plan-draft.json`). No escribes codigo, no modificas nada, solo lees y das veredicto.\r\n\r\n## Que evaluas\r\n\r\nRecibes un `plan-draft.json` con `archivos_tocados[]` (lista aprobada de archivos) y un `implementation.diff` (formato diff unificado).\r\n\r\nExtrae cada ruta de archivo tocada en el diff a partir de las lineas `diff --git a/<ruta> b/<ruta>` (o `--- a/<ruta>`/`+++ b/<ruta>`) — la linea `new file mode <modo>` NO contiene ninguna ruta, solo el modo de permisos del archivo nuevo; ignorala como fuente de ruta. Para archivos renombrados (`diff --git a/<ruta_vieja> b/<ruta_nueva>` junto con `similarity index`/`rename from`/`rename to`), evalua AMBAS rutas (vieja y nueva) contra `archivos_tocados[]` — si cualquiera de las dos esta en el plan, no es hallazgo. Para cada ruta, verifica si aparece en `archivos_tocados[]` del plan (ver reglas de comparacion abajo). Una ruta del diff ausente de `archivos_tocados[]` es un archivo fuera de alcance.\r\n\r\n## Reglas\r\n\r\n- **Solo lectura.** Tu salida es un veredicto, quien te invoco decide que hacer con el.\r\n- Compara rutas de forma literal (mismo string) — no infieras equivalencia entre rutas parecidas, salvo la normalizacion de separador descrita abajo.\r\n- **Normalizacion de separador de ruta**: antes de comparar, convierte `\\` a `/` en ambos lados (ruta extraida del diff y cada entrada de `archivos_tocados[]`). Este framework corre en Windows/PowerShell y algunos scripts pueden emitir rutas con backslash — la comparacion es insensible a esa diferencia, pero sigue siendo literal en todo lo demas.\r\n- **Sensibilidad a mayusculas**: la comparacion es case-sensitive por defecto (`Archivo.ts` != `archivo.ts`), salvo que el propio `archivos_tocados[]` indique explicitamente lo contrario.\r\n- Si todas las rutas del diff estan en `archivos_tocados[]`, no hay hallazgo: `VERDICT: pass`.\r\n- Cuando hay mas de un archivo fuera de alcance, el `reason` cita el primero encontrado en el diff (no los enumera todos).\r\n- No confundas \"fuera de alcance\" con \"complejidad innecesaria\" ni \"modificacion accidental\" (esas 2 categorias las cubre `unintended-change-detector` del Execution Checks) — tu unico criterio es: ¿la ruta esta en `archivos_tocados[]` si o no?\r\n\r\n## Veredicto — formato estructurado obligatorio\r\n\r\n```\r\nVERDICT: pass\r\n```\r\n\r\no\r\n\r\n```\r\nVERDICT: blocked | reason: \"<ruta literal>\" no esta en archivos_tocados[] del plan\r\n```\r\n\r\nLa ultima linea no vacia de tu respuesta es siempre el `VERDICT`. `reason` cita la ruta literal del archivo fuera de alcance — nunca una descripcion generica. Devuelve solo esto, nada de ensayo largo.\r\n"},{"name":"bossdream-smoker","group":"Pruebas y QA","description":"Ejecuta el codigo real del increment con casos adversariales/limite derivados de su superficie de entrada (parametros, campos, args) para encontrar bugs funcionales antes de reportar done (Fase 6.5 de /bossdream-implement, entre bossdream-solid-auditor y bossdream-design-auditor). Se invoca solo si el increment creo/modifico una superficie de entrada ejecutable (funcion publica, endpoint, formulario, comando CLI); si no hay superficie nueva, no se invoca. Si el increment toca UI lo ejercita en navegador (Playwright) y si persiste datos confirma la fila escrita con dbhub (solo lectura). Corre exclusivamente contra el entorno local del increment, nunca contra servicios externos o produccion. No corrige codigo -- solo ejecuta y reporta; un veredicto HALLAZGOS bloquea el increment y lo regresa al agente bossdream-coder.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","Bash","mcp__plugin_bossdream-core_playwright","mcp__plugin_bossdream-core_dbhub"],"model":"sonnet","source":"---\nname: bossdream-smoker\ndescription: Ejecuta el codigo real del increment con casos adversariales/limite derivados de su superficie de entrada (parametros, campos, args) para encontrar bugs funcionales antes de reportar done (Fase 6.5 de /bossdream-implement, entre bossdream-solid-auditor y bossdream-design-auditor). Se invoca solo si el increment creo/modifico una superficie de entrada ejecutable (funcion publica, endpoint, formulario, comando CLI); si no hay superficie nueva, no se invoca. Si el increment toca UI lo ejercita en navegador (Playwright) y si persiste datos confirma la fila escrita con dbhub (solo lectura). Corre exclusivamente contra el entorno local del increment, nunca contra servicios externos o produccion. No corrige codigo -- solo ejecuta y reporta; un veredicto HALLAZGOS bloquea el increment y lo regresa al agente bossdream-coder.\ntools: Read, Grep, Glob, Bash, mcp__plugin_bossdream-core_playwright, mcp__plugin_bossdream-core_dbhub\nmodel: sonnet\n---\n\nEres un probador funcional adversarial. No implementaste el increment; tu trabajo es intentar romperlo con entradas reales, no leerlo y opinar.\n\n## Como derivas los casos\n\nLeés la firma real de lo que el increment tocó (parámetros de función, campos de un formulario/DTO, query params, argumentos de CLI) — nunca le preguntás al `bossdream-coder` qué probar, nunca asumís sin leer el código. Para cada parámetro/campo con tipo o validación identificable, adaptás el catálogo de abajo a su tipo real.\n\n## Catálogo de casos base (adaptar según la firma encontrada)\n\n- **String**: sobredimensionado (miles de caracteres), vacío, unicode/caracteres especiales, caracteres de inyección (SQL/shell-metachar si el campo llega a una query o a un comando).\n- **Numérico**: tipo incorrecto (texto en campo numérico), fuera de rango, negativo donde no aplica, cero en denominador/índice.\n- **Requerido/opcional**: campo requerido omitido, campo opcional con valor límite.\n- **Colección/array**: vacío, con un elemento inválido mezclado.\n\n## Cómo ejecutás\n\nInvocación directa de la función/script/CLI, o `curl`/cliente HTTP contra el servidor que el propio increment levantó **localmente** — nunca contra un servicio externo ni producción.\n\n- **Interfaz**: si el increment toca UI y el campo `Verificación funcional:` lo pide, abrís la página local con `playwright`, recorrés el flujo feliz y las validaciones rutinarias (campo requerido vacío, formato inválido) y adjuntás captura o snapshot como evidencia.\n- **Datos**: si el increment persiste y hay `db_dsn` configurado, confirmás con `dbhub` que la fila quedó escrita tal como el flujo la produjo. Solo lectura: nunca `INSERT`/`UPDATE`/`DELETE`. Sin `dbhub` conectado, esa verificación es `NO-EJECUTABLE` con la razón, no `PASS`.\n- **No aplica**: si el increment no toca UI ni datos, esa verificación se declara `no aplica` con una frase de justificación; no se inventa.\n\nSi no hay forma de invocar el código en este entorno (falta runtime, falta servidor, falta dato de conexión), no lo simulás ni lo asumís: reportás `NO-EJECUTABLE` con la razón concreta.\n\n## Veredicto — formato estructurado obligatorio\n\n```\nVEREDICTO: PASS | HALLAZGOS | NO-EJECUTABLE\nRazon: [1 oracion]\n\nCASOS EJECUTADOS:\n[input usado] -> [resultado obtenido] (esperado: [resultado esperado])\n\nHALLAZGOS (si aplica):\n[caso] — [archivo:linea si aplica] — Alta/Media/Baja\n  Escenario de falla: [input concreto -> resultado incorrecto/crash]\n\nRAZON NO-EJECUTABLE (si aplica): [por que no hay superficie/entorno]\n```\n\n## Reglas\n\n- Solo ejecutás y reportás. Nunca corregís código — eso es trabajo del `bossdream-coder`.\n- Bash únicamente para invocar/inspeccionar el código del increment, nunca para editarlo.\n- Nunca contra servicios externos ni producción — solo el entorno local que el propio increment levantó. La base de datos se consulta solo en lectura.\n- Si no hay superficie de entrada ejecutable nueva/modificada en el increment, o no hay forma de invocarla en este entorno: `NO-EJECUTABLE`, no `HALLAZGOS` ni `PASS` forzado.\n- Sin placeholders: cada caso reportado debe haberse ejecutado realmente, nunca ser hipotético.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `playwright`: abrir la UI, ejercitar el flujo y capturar evidencia cuando el increment toca interfaz.\n- `dbhub`: confirmar que lo que el increment persiste quedo escrito (solo lectura, nunca escritura).\n"},{"name":"bossdream-solid-auditor","group":"Auditoría de código","description":"Auditor de arquitectura y SOLID. Se invoca una vez sobre el conjunto de archivos de codigo modificados en la tarea, antes de reportar done (Fase 6 de /bossdream-implement). Solo lee y reporta, nunca modifica. Excepcion: diff <=1 archivo y <=15 lineas netas -> revision inline sin spawn.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_codebase-memory","mcp__plugin_bossdream-core_serena"],"model":"haiku","source":"---\nname: bossdream-solid-auditor\ndescription: \"Auditor de arquitectura y SOLID. Se invoca una vez sobre el conjunto de archivos de codigo modificados en la tarea, antes de reportar done (Fase 6 de /bossdream-implement). Solo lee y reporta, nunca modifica. Excepcion: diff <=1 archivo y <=15 lineas netas -> revision inline sin spawn.\"\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_codebase-memory, mcp__plugin_bossdream-core_serena\nmodel: haiku\n---\n\nEres un auditor de arquitectura SOLID. Das una opinion objetiva e independiente sobre la salud del codigo — no lo implementaste tu.\n\n## Principios que evaluas\n\n- **S**: ¿Mas de una razon de cambio? ¿Mezcla dominio con infraestructura?\n- **O**: ¿if/switch sobre tipos que obligan a modificar codigo existente al extender?\n- **L**: ¿Subclases sustituibles sin romper el contrato de la base?\n- **I**: ¿Interfaces con metodos que los implementadores no necesitan?\n- **D**: ¿Dependencia de concretos? ¿new() dentro de logica de negocio?\n\n## Metricas\n\n- Nesting > 4 niveles o > 10 ramas en un metodo.\n- Acoplamiento: clases externas directas.\n- Cohesion: ¿todos los metodos operan sobre el mismo estado?\n- Nombre de helper/funcion atado a un tipo o dominio unico (ej. `InvoiceExporter.toCsv`, `formatearFechaFactura`) cuyo cuerpo no referencia realmente ese dominio (no usa sus campos ni logica especifica) y es candidato a reutilizarse en 2+ contextos — deberia llevar un nombre generico (ej. `Exporter.toCsv`, `formatearFecha`).\n\n## Comparación global\n\nCuando el diff introduce una funcion o clase nueva con logica no trivial (no un getter/setter ni un helper de una linea sin logica), usa Grep sobre el resto del proyecto (fuera de los archivos del diff) buscando funciones/clases con responsabilidad equivalente — mismo verbo+sustantivo de negocio, misma forma de entrada/salida. Si encuentras una equivalente, repórtalo en VIOLACIONES SOLID con `[Principio: S/duplicación]`, citando ambas ubicaciones (la nueva y la equivalente encontrada) y, en el Refactor minimo, el nombre del archivo/simbolo equivalente para que quede referenciado explicitamente.\n\n## Comentarios\n\nReporta como violacion de estilo: comentarios de mas de 1 linea, comentarios que explican QUE hace el codigo, comentarios de documentacion tipo docstring (XML docs/JSDoc/etc.) de mas de 3 lineas, breadcrumbs de IA.\n\n## Veredicto — formato estructurado obligatorio\n\n```\nVEREDICTO: PASS | OBSERVACIONES | RECHAZADO\nRazon: [1 oracion]\n\nVIOLACIONES SOLID:\n[Principio] — [Clase:Metodo:Linea] — Alta/Media/Baja\n  Impacto: [que se rompe]\n  Refactor minimo: [cambio mas pequeño que resuelve]\n\nVIOLACIONES DE ESTILO:\n[tipo] — [ubicacion] — [accion]\n\nMETRICAS: complejidad / acoplamiento (N) / cohesion (alta|media|baja)\n```\n\n## Modo `--scope global` (salida JSON, aditivo)\n\nEste modo es aditivo: el `VEREDICTO`/`VIOLACIONES SOLID` de arriba sigue siendo la salida normal cuando se invoca sin flags (uso post-tarea de Fase 6, callers existentes) — este modo nunca lo reemplaza.\n\nSe activa solo con el flag explícito `--scope global` (uso: consumo automatizado/machine-parseable, no el chequeo normal post-tarea). Ejecuta la misma logica de \"## Comparación global\" y del chequeo de nombre atado a un tipo (\"## Metricas\"), pero la unica salida es un array JSON `hallazgos[]` — sin VEREDICTO, sin VIOLACIONES SOLID, sin VIOLACIONES DE ESTILO, sin METRICAS:\n\n```json\n[\n  {\n    \"tipo\": \"duplicacion_global\" | \"nombre_atado_a_tipo\",\n    \"ubicacion\": \"<archivo>:<línea>\",\n    \"equivalente_a\": \"<archivo>:<línea>\" | null,\n    \"recomendacion\": \"<string>\"\n  }\n]\n```\n\n`equivalente_a` es no-null solo cuando `tipo` es `\"duplicacion_global\"` (apunta al archivo/simbolo equivalente encontrado); en `\"nombre_atado_a_tipo\"` siempre es `null`. La regla de `AUTORIZACION REQUERIDA: ...` (ver \"## Reglas\") sigue aplicando sin cambios en este modo: cuando un hallazgo implica rename, esa linea se emite despues del array JSON, como ultima linea de toda la respuesta.\n\n## Reglas\n\n- Solo lectura. Never modificar archivos.\n- Refactor minimo siempre; no reescrituras completas salvo caso extremo.\n- No reportar violaciones Baja puramente teoricas.\n- Los controladores/handlers de UI del framework (Controllers, ViewControllers, componentes de pagina/ruta) tienen responsabilidades inherentes a ese rol — no confundir con violaciones S.\n- Devuelve el veredicto estructurado, no un ensayo (economia de tokens del hilo principal).\n- Cuando una violacion detectada por \"Comparación global\" o por el chequeo de nombre atado a un tipo (bloque Metricas) implica renombrar o unificar simbolos, el \"Refactor minimo\" de esa violacion termina con la marca literal `REQUIERE AUTORIZACIÓN DEL USUARIO` — nunca la aplicas, solo la propones (refuerzo de \"Solo lectura\" para este caso especifico). Ademas, cierra tu respuesta completa con una linea `AUTORIZACION REQUERIDA: renombrar <nombre_actual> a <nombre_propuesto>? (sí/no)` por cada hallazgo que implique rename/unificacion — una linea por hallazgo, en el mismo orden en que aparecen en el reporte/array, todas al final, sin nada despues de la ultima.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `codebase-memory`: dependencias entre modulos para juzgar SRP/DIP.\n- `serena`: referencias de un simbolo para juzgar OCP/LSP sin leer archivos completos.\n"},{"name":"bossdream-traceability-watcher","group":"Auditoría de código","description":"Auditor de la cadena Requirement -> Plan -> Code -> Test -> Evidence. Se invoca fresco, 0 historial previo, recibiendo la tabla de `/execution-checks --check plan-to-code-traceability` (columnas requirement/ac/plan_step/code_change/test/qa_evidence). Reporta el eslabon roto exacto: la primera columna vacia en la cadena.","args":[],"userOnly":false,"tools":["Read","Grep","Glob","mcp__plugin_bossdream-core_codebase-memory"],"model":"haiku","source":"---\nname: bossdream-traceability-watcher\ndescription: \"Auditor de la cadena Requirement -> Plan -> Code -> Test -> Evidence. Se invoca fresco, 0 historial previo, recibiendo la tabla de `/execution-checks --check plan-to-code-traceability` (columnas requirement/ac/plan_step/code_change/test/qa_evidence). Reporta el eslabon roto exacto: la primera columna vacia en la cadena.\"\ntools: Read, Grep, Glob, mcp__plugin_bossdream-core_codebase-memory\nmodel: haiku\n---\n\nEres un auditor de trazabilidad para cadenas Requirement->Plan->Code->Test->Evidence. No escribes codigo, no modificas nada, solo lees y das veredicto.\n\n## Que evaluas\n\nRecibes una tabla (o el JSON equivalente) con columnas `requirement/ac/plan_step/code_change/test/qa_evidence`, una fila por elemento trazado.\n\nPara cada fila, recorre las columnas en orden (`requirement` -> `ac` -> `plan_step` -> `code_change` -> `test` -> `qa_evidence`). La primera columna vacia de una fila es el eslabon roto de esa fila — nombra el par de columnas que representa ese eslabon (ej. columna `test` vacia = eslabon `code_change -> test` roto).\n\n**Antes de reportar, descarta columnas uniformemente vacias en TODAS las filas** (gap sistemico ya conocido/documentado a nivel de todo el artefacto, ej. `requirement`/`ac` vacios en cada fila por una limitacion de formato ya aceptada) — esas no son el eslabon roto que este auditor reporta. El hallazgo real es la primera columna vacia en una fila que NO esta vacia en las demas filas (hueco especifico de esa fila, no del artefacto entero). Si todas las columnas vacias son uniformes en todas las filas, no hay eslabon roto que reportar: `VERDICT: pass`.\n\n**Nombrado del eslabon cuando la(s) columna(s) anterior(es) tambien estan descartadas por sistemicas**: si la columna que precede a la primera columna vacia-no-sistemica esta ella misma descartada por ser sistemicamente vacia (regla anterior), el nombre del eslabon se construye igual con las 2 columnas adyacentes en el orden canonico de la cadena (`requirement -> ac -> plan_step -> code_change -> test -> qa_evidence`), citando el nombre de ambas columnas tal cual — nunca sustituyas la columna anterior por la columna sistemica no descartada mas cercana. Ejemplo concreto: `requirement` y `ac` estan vacias en TODAS las filas (gap sistemico, descartado), y en una fila especifica `plan_step` esta vacio pero `requirement`/`ac`/`plan_step` en las demas filas tienen `plan_step` poblado — el eslabon roto de esa fila se nombra `ac -> plan_step` (las 2 columnas canonicas adyacentes a la vacia), no se sustituye `ac` por ninguna otra columna.\n\n## Reglas\n\n- **Solo lectura.** Tu salida es un veredicto, quien te invoco decide que hacer con el.\n- Si todas las filas tienen las 6 columnas completas, no hay eslabon roto: `VERDICT: pass`.\n- Cuando hay mas de una fila con eslabon roto, el `reason` cita la primera fila encontrada (identificada por su `requirement`/`ac` o por el valor de `code_change`, lo que este disponible en la fila).\n- Una columna vacia mas adelante en la misma fila no es un hallazgo adicional — solo el primer eslabon roto de cada fila importa (los siguientes son consecuencia del mismo corte de cadena).\n\n## Veredicto — formato estructurado obligatorio\n\n```\nVERDICT: pass\n```\n\no\n\n```\nVERDICT: blocked | reason: eslabon Code Change -> Test roto en la fila de \"<code_change o requirement de esa fila>\": columna test vacia\n```\n\nLa ultima linea no vacia de tu respuesta es siempre el `VERDICT`. `reason` identifica la fila concreta y el par de columnas del eslabon roto — nunca una descripcion generica. Devuelve solo esto, nada de ensayo largo.\n\n## MCP disponibles\nSi un servidor no esta conectado, su herramienta no aparece: sigue sin ella y declara en tu respuesta que no pudiste usarla.\n- `codebase-memory`: seguir la cadena requisito a codigo y detectar codigo sin prueba.\n"}],"mcp":[{"name":"sequentialthinking","package":"@modelcontextprotocol/server-sequential-thinking@1.0.0","runner":"npx","note":"Razonamiento estructurado multipaso."},{"name":"context7","package":"@upstash/context7-mcp@4.3.0","runner":"npx","note":"Documentación actualizada de librerías."},{"name":"fetch","package":"mcp-fetch-server@1.1.2","runner":"npx","note":"Trae páginas web como md, txt o json."},{"name":"codebase-memory","package":"codebase-memory-mcp@0.11.0","runner":"npx","note":"Grafo de código y búsqueda semántica."},{"name":"playwright","package":"@playwright/mcp@0.0.83","runner":"npx","note":"Navegador: capturas, snapshot de accesibilidad, red y consola."},{"name":"dbhub","package":"@bytebase/dbhub@1.5.0","runner":"npx","note":"SQL de solo lectura sobre MySQL, MariaDB, PostgreSQL, SQL Server o SQLite."},{"name":"a11y","package":"a11y-mcp@1.1.0","runner":"npx","note":"Auditoría de accesibilidad (axe-core) sobre páginas http(s)."},{"name":"mdn","package":"mdn-mcp@1.0.0","runner":"npx","note":"Compatibilidad de CSS, HTML y JS por navegador."},{"name":"colors","package":"@colorsandfonts/mcp@1.1.0","runner":"npx","note":"Paletas, escalas y contraste de color."},{"name":"mermaid","package":"mcp-mermaid@0.4.1","runner":"npx","note":"Renderiza diagramas Mermaid."},{"name":"serena","package":"git+https://github.com/oraios/serena@v1.7.0","runner":"uvx","note":"Navegación y edición a nivel de símbolo vía LSP."}],"templates":{"core":[{"path":".claude/rules/comentarios.md","note":"","content":"---\r\npaths: [\"**/*.cs\", \"**/*.razor\", \"**/*.sql\", \"**/*.css\", \"**/*.scss\", \"**/*.ps1\"]\r\n---\r\n\r\n# Comentarios — tolerancia cero\r\n\r\nProhibido: bloques multi-linea (`/* */`, `/** */`, `//`/`#`/`--` en 2+ lineas seguidas segun el lenguaje, `@* *@` multi-linea, `<# #>` multi-linea en PowerShell), comentarios que explican QUE hace el codigo, breadcrumbs de IA (`// Added for X`), tono narrativo, redundancia con el nombre del simbolo, separadores decorativos y `#region`.\r\n\r\nUnico permitido: 1 linea con WHY no inferible del codigo. Si el WHY es deducible → silencio.\r\n\r\nXML docs (C# `///`): max 3 lineas, solo en APIs publicas de libreria o interfaces de contrato.\r\n\r\n**El comentario correcto depende del lenguaje del archivo** — el hook `comment-check` solo aplica el patron del dialecto real de cada extension (`.sql` → `--`; `.ps1`/`.psm1`/`.psd1` → `#` y `<# #>`; `.cs`/`.js`/`.ts`/`.razor`/etc. → `//` y `/* */`; `.razor`/`.cshtml` ademas `@* *@`). Un `--flag` de CLI en un `.ps1`, o cualquier texto que solo *parezca* comentario de otro lenguaje, no se evalua contra el patron equivocado.\r\n\r\nEl hook `comment-check` bloquea las violaciones antes de escribir.\r\n"},{"path":".claude/settings.json","note":"","content":"{\n  \"extraKnownMarketplaces\": {\n    \"bossdream\": { \"source\": { \"source\": \"github\", \"repo\": \"MiguelALRendon/BossDream\" } }\n  },\n  \"enabledPlugins\": {\n    \"bossdream-core@bossdream\": true\n  },\n  \"permissions\": {\n    \"allow\": [],\n    \"deny\": [\n      \"Read(./.env)\",\n      \"Read(./**/secrets*.json)\"\n    ]\n  },\n  \"hooks\": {\n    \"SessionStart\": [\n      { \"hooks\": [ { \"type\": \"command\", \"command\": \"command -v pwsh >/dev/null 2>&1 || echo \\\"BossDream: falta PowerShell 7 (pwsh) y los hooks de calidad no se ejecutaran. Windows: winget install Microsoft.PowerShell. Linux/macOS: https://learn.microsoft.com/powershell/scripting/install/installing-powershell\\\"\", \"timeout\": 10 } ] }\n    ],\n    \"PreToolUse\": [\n      { \"matcher\": \"Edit|Write|MultiEdit\", \"hooks\": [\n        { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/plan-lock.ps1\\\"\", \"timeout\": 20 },\n        { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/comment-check.ps1\\\"\", \"timeout\": 30 }\n      ]},\n      { \"matcher\": \"Bash\", \"hooks\": [\n        { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/command-lock.ps1\\\"\", \"timeout\": 15 }\n      ]},\n      { \"matcher\": \"Grep|Glob|Read\", \"hooks\": [\n        { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/read-budget.ps1\\\"\", \"timeout\": 15 }\n      ]}\n    ],\n    \"PostToolUse\": [\n      { \"matcher\": \"Edit|Write|MultiEdit\", \"hooks\": [\n        { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/mark-dirty.ps1\\\"\", \"timeout\": 10 },\n        { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/sync-agent-models.ps1\\\"\", \"timeout\": 15 }\n      ]}\n    ],\n    \"UserPromptSubmit\": [\n      { \"hooks\": [ { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/readiness.ps1\\\"\", \"timeout\": 15 } ] },\n      { \"hooks\": [ { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/active-project-context.ps1\\\"\", \"timeout\": 15 } ] }\n    ],\n    \"Stop\": [\n      { \"hooks\": [ { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/stop-completion.ps1\\\"\", \"timeout\": 600 } ] }\n    ]\n  }\n}\n"},{"path":".editorconfig","note":"","content":""},{"path":".gitignore","note":"","content":".claude/settings.local.json\r\n.claude/.completion-state.json\r\n.claude/.active-plan\r\n.claude/.work-mode\r\n.claude/.bossdream-dirty\r\n.claude/.line-budget.json\r\nbin/\r\nobj/\r\nStrykerOutput/\r\n"},{"path":"bossdream.json","note":"plan-lock, extensiones de código, pruebas, estilos, QA y ruteo de modelos.","content":"{\r\n  \"codeExtensions\": [\r\n    \".css\",\r\n    \".scss\",\r\n    \".sql\",\r\n    \".ps1\"\r\n  ],\r\n  \"planLock\": {\r\n    \"enabled\": true,\r\n    \"requirePaths\": [],\r\n    \"exemptPaths\": [\r\n      \"tests/**\",\r\n      \"docs/**\",\r\n      \"scripts/**\",\r\n      \"scratch/**\",\r\n      \"plans/**\",\r\n      \"**/*.md\",\r\n      \"**/*.feature\"\r\n    ],\r\n    \"exemptModes\": [\r\n      \"spike\",\r\n      \"explore\",\r\n      \"bugfix\",\r\n      \"chore\",\r\n      \"implement\"\r\n    ],\r\n    \"nonEditingModes\": [\r\n      \"plan\",\r\n      \"document\",\r\n      \"review\"\r\n    ]\r\n  },\r\n  \"testing\": {\r\n    \"enabled\": true,\r\n    \"bdd\": false,\r\n    \"project\": \"\",\r\n    \"coverage\": \"changed\",\r\n    \"exemptions\": [\r\n      \"accesores-simples\",\r\n      \"contenedores-de-datos\",\r\n      \"constructores-triviales\",\r\n      \"catalogos-repetidos\",\r\n      \"mapeos-1a1\",\r\n      \"autogenerado\",\r\n      \"cableado-configuracion\",\r\n      \"presentacion-ui\"\r\n    ]\r\n  },\r\n  \"style\": {\r\n    \"enabled\": false,\r\n    \"themeSource\": \"\",\r\n    \"vendorExempt\": [],\r\n    \"exemptions\": [\r\n      \"0\",\r\n      \"porcentajes\",\r\n      \"viewport\",\r\n      \"grid-fr\",\r\n      \"keywords\"\r\n    ]\r\n  },\r\n  \"qa\": { \"mode\": \"costoso\" },\n  \"models\": {\r\n    \"plan\": \"opus\",\r\n    \"code\": \"sonnet\",\r\n    \"audit\": \"haiku\",\r\n    \"quick\": \"haiku\"\r\n  }\r\n}\r\n"},{"path":"CLAUDE.md","note":"Instrucciones del agente: ciclo requerido, comentarios, stack.","content":"# Instrucciones del agente\r\n\r\nEste proyecto usa el framework **BossDream**. El flujo detallado y las reglas viven en skills; aqui solo lo esencial.\r\n\r\n## Contexto\r\n\r\nCore Tenets en @docs/constitution.md. Mapa del sistema en @docs/ARCHITECTURE.md.\r\n\r\n## Required Cycle\r\n\r\nTarea no trivial (>1 archivo o >15 lineas netas, decision de arquitectura, ambiguedad, o algo nuevo) → invocar la skill `bossdream` antes de tocar nada. \"Done\" = gates del `completion.json` en verde con evidencia mostrada, no la palabra \"listo\" (lo verifica el Stop hook).\r\n\r\n## Comentarios\r\n\r\nTolerancia cero. Regla en @.claude/rules/comentarios.md, aplicada de forma determinista por el hook `comment-check`.\r\n\r\n## Stack\r\n\r\n<completar: lenguaje, framework, ORM, base de datos, convenciones propias del equipo>\r\n"},{"path":"completion.json","note":"Gates del Completion Criteria y tope de reintentos.","content":"{\r\n  \"gates\": [\r\n    { \"id\": \"pipeline\", \"required\": true, \"check\": \"pipeline --local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"tasks\", \"required\": true, \"check\": \"tasks-complete\", \"blocking\": \"hard\" },\r\n    { \"id\": \"evidence\", \"required\": false, \"goal\": \"transcript shows 'pipeline OK' and audit verdicts\" },\r\n    { \"id\": \"semantic-verify\", \"required\": false, \"agent\": \"bossdream-endless-verifier\", \"when\": \"nontrivial\" },\r\n    { \"id\": \"qa-manager\", \"required\": true, \"agent\": \"bossdream-qa-planner\", \"when\": \"qa-increment\", \"blocking\": \"hard\" }\r\n  ],\r\n  \"maxBlocks\": 8,\r\n  \"onExhausted\": \"handoff-report\"\r\n}\r\n"},{"path":"docs/adr/0000-template.md","note":"","content":"---\r\nstatus: proposed\r\ndate: YYYY-MM-DD\r\ndeciders: []\r\n---\r\n\r\n# NNNN. Titulo de la decision\r\n\r\n## Context and Problem Statement\r\n\r\nQue problema se resuelve y por que ahora.\r\n\r\n## Considered Options\r\n\r\n- Opcion A\r\n- Opcion B\r\n\r\n## Decision Outcome\r\n\r\nElegida: **Opcion A**, porque <justificacion anclada a la realidad, no inventada>.\r\n\r\n### Consequences\r\n\r\n- Positiva: <...>\r\n- Negativa: <...>\r\n- Neutral: <...>\r\n\r\n## More Information\r\n\r\nEnlaces a plans, otros ADR (`superseded-by`), o discusion.\r\n"},{"path":"docs/architecture/context.mmd","note":"","content":""},{"path":"docs/ARCHITECTURE.md","note":"","content":"# Arquitectura\n\n> Overview de alto nivel + puntos de entrada al codigo. Claude mantiene este archivo contra el codigo real; no dupliques lo que ya vive en el codigo, enlazalo.\n\n## Vista general\n\n<1-2 parrafos: que es el sistema y sus piezas principales>\n\n## Diagramas C4\n\n- Contexto y contenedores: @docs/architecture/context.mmd\n\n## Puntos de entrada\n\n<archivos/clases desde donde empezar a leer el codigo>\n\n## Decisiones\n\nLas decisiones significativas viven como ADRs en @docs/adr/. Ver el indice ahi.\n"},{"path":"docs/catalog/.gitkeep","note":"","content":""},{"path":"docs/concepts/.gitkeep","note":"","content":""},{"path":"docs/constitution.md","note":"","content":"# Constitucion del proyecto\r\n\r\n> Rellena este archivo con los principios que rigen el proyecto. Es la fuente que gobierna CLAUDE.md y los ADRs. No lo dejes vacio: el flujo pleno no arranca hasta que tenga contenido.\r\n\r\n## Proposito\r\n\r\n<que resuelve este proyecto y para quien>\r\n\r\n## Core Tenets\r\n\r\n<reglas no negociables propias del equipo; ej. \"todo acceso a datos via XPO\", \"sin logica en el editor\">\r\n\r\n## Restricciones\r\n\r\n<tecnicas, de negocio, de cumplimiento>\r\n\r\n## Definicion de calidad\r\n\r\n<que significa \"bien hecho\" aqui: cobertura minima, que se testea siempre, que nunca se hace>\r\n\r\n## Fuera de alcance\r\n\r\n<lo que este proyecto explicitamente NO hace>\r\n"},{"path":"docs/human-explanations/.gitkeep","note":"","content":""},{"path":"docs/README.md","note":"","content":"# Documentacion\r\n\r\nEstructura Diataxis: cada archivo pertenece a **un solo** modo. No mezclar.\r\n\r\n| Carpeta | Modo | Orientacion |\r\n|---|---|---|\r\n| `human-explanations/` | Human explanation | Aprender de la mano (onboarding) |\r\n| `to-skills/` | To-skill | Resolver una tarea concreta |\r\n| `catalog/` | Catalog | Descripcion sistematica (API, config, esquema) |\r\n| `concepts/` | Concept | Por que, trade-offs, contexto |\r\n\r\nOtras carpetas:\r\n- `_inbox/` — buzon de notas informales; `/docs-rewrite` las procesa a los 4 modos.\r\n- `adr/` — Architecture Decision Records (MADR), inmutables.\r\n- `architecture/` — diagramas C4 (Mermaid).\r\n\r\nLas plans ejecutables (`.feature` Gherkin) viven en `plans/`, no aqui.\r\n"},{"path":"docs/TECH_DEBT.md","note":"","content":"# Tech Debt Ledger\n\n> Running register of technical debt found by the `tech-debt` skill. **Advisory only — nothing here blocks a build or a plan.** Update `Status` as items are paid down.\n>\n> Status values: `open` · `in-progress` · `paid` · `wont-fix`. Effort: `low` · `medium` · `high`.\n\n| ID | Location | Category | Impact | Remediation | Effort | Status |\n|----|----------|----------|--------|-------------|--------|--------|\n|    |          |          |        |             |        |        |\n"},{"path":"docs/to-skills/.gitkeep","note":"","content":""},{"path":"docs/_inbox/README.md","note":"","content":"# _inbox — buzon de documentacion informal\r\n\r\nTira aqui tus notas tal cual: ideas, decisiones, explicaciones, sin formato ni estructura. Un archivo por tema o uno solo, da igual.\r\n\r\nCuando termines, ejecuta `/docs-rewrite`. Convierte esto en documentacion IA-friendly (Diataxis + ADR), **sin perder tus ideas ni inventar nada**: lo que no pueda anclar al codigo te lo pregunta, no lo adivina.\r\n\r\nAl procesarse, el contenido migra a `human-explanations/`, `to-skills/`, `catalog/`, `concepts/` o `adr/`, y este buzon queda vacio.\r\n"},{"path":"gitignore-snippet.txt","note":"Entradas que se añaden al .gitignore.","content":".claude/.active-project\r\n"},{"path":"pipeline.json","note":"Etapas agnósticas del pipeline (theme-check, gherkin, docdrift).","content":"{\r\n  \"stages\": [\r\n    { \"id\": \"theme-check\", \"order\": 3, \"internal\": \"style-check\", \"tier\": \"local\", \"blocking\": \"hard\", \"requiresStyle\": true },\r\n    { \"id\": \"gherkin\", \"order\": 4, \"internal\": \"gherkin-check\", \"tier\": \"local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"docdrift\", \"order\": 11, \"internal\": \"docdrift-check\", \"tier\": \"ci\", \"blocking\": \"soft\", \"enabled\": false }\r\n  ]\r\n}\r\n"},{"path":"plan-progress.json","note":"Avance de un plan por increments.","content":"{\n  \"status\": \"not-started\",\n  \"planned\": [],\n  \"pending\": []\n}\n"},{"path":"plans/_TEMPLATE/example.feature","note":"","content":""},{"path":"plans/_TEMPLATE/plan.md","note":"","content":"# Plan — <feature>\r\n\r\n> Producto de `/bossdream-plan`. Referencia: `spec.md` (QUE), `design.md` (diseno aprobado). **Regla dura: sin placeholders.**\r\n\r\n## Razon de ser\r\n<por que existe este plan; el problema/objetivo real>\r\n\r\n## Justificacion\r\n<por que este enfoque; alternativas consideradas -> ADR-NNNN>\r\n\r\n## Flujo (que / por que)\r\n<narrativa breve de que se hace y por que>\r\n\r\n## Clasificacion\r\ntipo: modify-flow | add-to-flow | new   ·   complejidad: trivial | task | large\r\n\r\n## Investigacion (research-log)\r\n| Pregunta | Tool/agente | Hallazgo | Como informo el plan |\r\n|---|---|---|---|\r\n|  |  |  |  |\r\n\r\n## Impacto cross-flow\r\n| Flujo afectado | Verificado con | ¿Choca? | Mitigacion |\r\n|---|---|---|---|\r\n|  |  |  |  |\r\n\r\n## Deuda tecnica (informativa, NO bloqueante)\r\nHallazgos del skill `tech-debt` sobre los flujos que este plan toca. El usuario decide si se paga (agregando increments) o se deja registrada en `docs/TECH_DEBT.md`. No bloquea el plan.\r\n| Ubicacion | Deuda | Impacto | Remediacion | Esfuerzo | ¿Se paga en este plan? |\r\n|---|---|---|---|---|---|\r\n|  |  |  |  |  |  |\r\n\r\n## Decisiones (opcion elegida vs descartadas)\r\n| Decision | Elegida | Descartadas + por que | ADR |\r\n|---|---|---|---|\r\n|  |  |  |  |\r\n\r\n## Increments\r\n\r\n### Increment 1: <objetivo> — cubre spec [criterios]\r\n- Justificacion / fuentes: <por que este increment; evidencia archivo:linea / query / doc>\r\n- Pasos:\r\n  - [ ] 1.1 <paso codigo>    — skill · mcp · bossdream-coder · fuente: <archivo:linea / doc>\r\n  - [ ] 1.2 <paso no-codigo> — fuente/porque: <...>\r\n  - [ ] 1.y pruebas unitarias — generar/actualizar con test-gen (adversarial primero, happy path al final); solo codigo de logica, respeta exenciones\r\n  - [ ] 1.x doc-check         — revisar/actualizar docs del flujo\r\n- Conexiones: <skills enlazadas o \"sin skill aplicable\">\r\n- Pipeline del increment: <stages/tests scoped que lo validan>\r\n- Criterio de aceptacion: <verificable>\r\n- Verificacion funcional: navegador (flujo feliz + validaciones rutinarias) | datos (consulta de solo lectura via dbhub) | no aplica: <justificacion en una frase>\n- Revision de planeacion: PENDIENTE   (se marca PASO al agregarlo; requiere fuente+porque en cada paso)\r\n\r\n### Increment 2: <objetivo>\r\n- Pasos:\r\n  - [ ] 2.1 ...\r\n  - [ ] 2.y pruebas unitarias — test-gen (adversarial primero); solo codigo de logica\r\n  - [ ] 2.x doc-check\r\n- Conexiones: <skills enlazadas o \"sin skill aplicable\">\r\n- Pipeline del increment: ...\r\n- Criterio de aceptacion: ...\r\n- Verificacion funcional: navegador | datos | no aplica: <justificacion>\n- Revision de planeacion: PENDIENTE\n\n### Increment N (ultimo): QA Increment - cubre spec [todos los criterios]\n- Pasos:\n  - [ ] N.1 skill `qa-increment`: inventario de pruebas, QA Manager, `qa-run` en el modo de `bossdream.json > qa.mode`, Test Critic, re-verificacion\n- Conexiones: `qa-increment`, `qa-run`, `bossdream-qa-planner`, `bossdream-qa-auditor`\n- Pipeline del increment: `test-checks` en verde con veredicto `QA VERDICT: ACCEPTED`\n- Criterio de aceptacion: veredicto ACCEPTED sin razones abiertas\n- Verificacion funcional: la ejecuta `qa-run` (Playwright si hay UI, dbhub si hay datos)\n- Revision de planeacion: PENDIENTE\n"},{"path":"plans/_TEMPLATE/spec.md","note":"","content":"# Spec — <feature>\r\n\r\n> QUE y POR QUE. Frontera dura: sin codigo, sin el \"como\".\r\n\r\n## Problema\r\n\r\n<que necesidad resuelve, para quien>\r\n\r\n## Comportamiento esperado\r\n\r\n<que debe pasar, en lenguaje de negocio>\r\n\r\n## Criterios de aceptacion\r\n\r\n- [ ] <criterio verificable 1>\r\n- [ ] <criterio verificable 2>\r\n\r\n## Fuera de alcance\r\n\r\n<lo que esta feature NO hace>\r\n"},{"path":"plans/_TEMPLATE/tasks.md","note":"","content":"# Tareas — <feature>\r\n\r\n> Derivadas de plan.md. El Completion Criteria exige todas en `[x]` para la feature activa.\r\n\r\n- [ ] 1. <tarea>\r\n- [ ] 2. <tarea>\r\n- [ ] 3. Tests que cubren los criterios de aceptacion\r\n- [ ] 4. Escenarios .feature verdes\r\n"},{"path":"procedural-tutorial.md","note":"Plantilla de tutorial procedural.","content":"TRIGGER\r\n<cuando se dispara esta operacion, en que momento del flujo del usuario>\r\n\r\nPRECONDITIONS\r\n<que debe existir/estar listo antes de correr la operacion>\r\n\r\nINPUTS\r\n<parametros/datos requeridos, con sus nombres literales>\r\n\r\nPROCESS\r\n1. <primer paso real del script/flujo>\r\n2. <segundo paso>\r\n3. <tercer paso>\r\n\r\nDECISIONS\r\n<puntos de decision reales del script, si los hay>\r\n\r\nVALIDATION\r\n<como comprobar que la operacion tuvo exito, segun el codigo real>\r\n\r\nEVIDENCE\r\n<que artefacto/archivo queda como evidencia de que la operacion se hizo>\r\n\r\nANTI-PATTERNS\r\n<errores conocidos ya documentados sobre esta operacion>\r\n\r\nRELATED FLOWS\r\n<que otro flujo consume el resultado de esta operacion>\r\n"},{"path":"project.json","note":"Metadatos del proyecto de negocio.","content":"{\n  \"id\": \"\",\n  \"name\": \"\",\n  \"classification\": \"\",\n  \"status\": \"draft\",\n  \"createdAt\": \"\",\n  \"documentsPath\": \"\"\n}\n"},{"path":"settings.hooks-snippet.json","note":"Hooks de gobernanza que se fusionan en settings.json.","content":"{\n  \"hooks\": {\n    \"UserPromptSubmit\": [\n      {\n        \"hooks\": [\n          { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/validation-lock.ps1\\\"\", \"timeout\": 15 }\n        ]\n      },\n      {\n        \"hooks\": [\n          { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/plan-context-inject.ps1\\\"\", \"timeout\": 15 }\n        ]\n      }\n    ],\n    \"PostToolUse\": [\n      { \"matcher\": \"Edit|Write|MultiEdit\", \"hooks\": [\n        { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/mark-project-dirty.ps1\\\"\", \"timeout\": 10 }\n      ]}\n    ],\n    \"Stop\": [\n      {\n        \"hooks\": [\n          { \"type\": \"command\", \"command\": \"pwsh -NoProfile -ExecutionPolicy Bypass -File \\\"${CLAUDE_PROJECT_DIR}/.claude/bossdream-hooks/project-sync.ps1\\\"\", \"timeout\": 60 }\n        ]\n      }\n    ]\n  }\n}\n"},{"path":"traceability.json","note":"Grafo REQ → Epic → Feature → US → AC → TC.","content":"{}\n"},{"path":"vale/.vale.ini","note":"","content":""},{"path":"vale/styles/Validation/PalabrasDebiles.yml","note":"","content":"extends: existence\r\nmessage: \"Evita la palabra/frase débil '%s' — sé específico (lista inspirada en NASA ARM/QuARS).\"\r\nlevel: warning\r\nignorecase: true\r\ntokens:\r\n  - TBD\r\n  - 'etc\\.'\r\n  - adecuad[oa]s?\r\n  - apropiad[oa]s?\r\n  - segun corresponda\r\n  - lo necesario\r\n  - lo que aplique\r\n  - lo que sea necesario\r\n"},{"path":"vale/styles/Validation/VozPasivaExcesiva.yml","note":"","content":"extends: existence\r\nmessage: \"Posible voz pasiva excesiva: '%s' — prefiere voz activa y un responsable claro cuando sea posible.\"\r\nlevel: suggestion\r\nignorecase: true\r\ntokens:\r\n  - '(fue|fueron|es|son|será|serán)\\s+\\w+(ado|ada|ados|adas|ido|ida|idos|idas)\\s+por'\r\n"},{"path":"validation-rules.json","note":"Reglas del Document Validation.","content":"{\r\n  \"ambiguityQuestionThreshold\": 3,\r\n  \"stuckThreshold\": 3,\r\n  \"batchSize\": 12,\r\n  \"weakVocabulary\": [\"TBD\", \"etc.\", \"adecuado\", \"apropiado\", \"varios\", \"algunos\", \"segun corresponda\", \"lo necesario\", \"lo que aplique\"],\r\n  \"documentTypes\": {\r\n    \"requirements.md\": {\r\n      \"requiredSections\": [\r\n        \"Reglas de negocio relevantes\",\r\n        \"User Stories — siempre presente\",\r\n        \"Tabla resumen de trazabilidad\"\r\n      ],\r\n      \"semanticQuestions\": [\r\n        \"¿Hay contradiccion entre las Reglas de negocio relevantes y los criterios de aceptacion de alguna User Story?\",\r\n        \"¿Alguna User Story introduce alcance que ninguna Regla de negocio ni Feature/Epic respalda?\",\r\n        \"¿Los criterios de aceptacion son verificables sin ambiguedad, sin mezclar varios criterios en uno?\"\r\n      ]\r\n    },\r\n    \"tests/test-approach.md\": {\r\n      \"requiredSections\": [\r\n        \"1. Cuándo usar checklist vs. casos de prueba formales\",\r\n        \"2. Checklist de smoke test (Simple, y como base en Medio/Complejo)\",\r\n        \"7. Resumen de evidencia para cierre de QA\"\r\n      ],\r\n      \"semanticQuestions\": [\r\n        \"¿El enfoque de pruebas cubre todos los AC de requirements.md?\",\r\n        \"¿Hay AC sin ningun TC vinculado (huerfanos)?\"\r\n      ]\r\n    },\r\n    \"TC\": {\r\n      \"requiredFields\": [\"Escenario\", \"Precondiciones\", \"Datos de prueba\", \"Pasos\", \"Resultado esperado\", \"Resultado obtenido\", \"Evidencia\", \"Estado\"],\r\n      \"semanticQuestions\": [\r\n        \"¿Precondiciones/pasos/resultado esperado estan sin ambiguedad?\",\r\n        \"¿El TC prueba exactamente un AC, no varios criterios mezclados?\"\r\n      ]\r\n    }\r\n  }\r\n}\r\n"},{"path":"validation.json","note":"Estado inicial del gate de validación (blocked).","content":"{\r\n  \"overallStatus\": \"blocked\",\r\n  \"exemptions\": [],\r\n  \"documents\": {\r\n    \"requirements.md\": { \"status\": \"pending\", \"checks\": [] },\r\n    \"tests/test-approach.md\": { \"status\": \"pending\", \"checks\": [] }\r\n  }\r\n}\r\n"},{"path":"_PROJECT_TEMPLATE/overview.md","note":"","content":"# [Nombre de la iniciativa]\r\n\r\n**ID:** REQ-XXX\r\n**Clasificación:** Simple / Medio / Complejo\r\n**Estado:** Draft / Document Validation en progreso / Listo para planear / En desarrollo / Cerrado\r\n\r\n## Resumen ejecutivo\r\n[2-3 frases: qué es esto y para quién, en lenguaje de negocio.]\r\n\r\n## Documentos de esta iniciativa\r\n- [`understanding.md`](./understanding.md) — qué entendimos y qué vamos a construir\r\n- [`requirements.md`](./requirements.md) — Epics/Features/User Stories/Criterios de aceptación\r\n- [`tests/test-approach.md`](./tests/test-approach.md) — estrategia y casos de prueba\r\n- [`roadmap.md`](./roadmap.md) — índice de planeación (se genera al correr `/bossdream-plan`, no antes)\r\n\r\n## Estado del gate de Document Validation\r\n[Se actualiza por `/bossdream-validate` — ver `.bossdream-project/validation.json`. No editar a mano.]\r\n"},{"path":"_PROJECT_TEMPLATE/requirements.md","note":"","content":"# Requerimientos Funcionales — [Nombre de la iniciativa]\r\n\r\n**ID de iniciativa (Entendimiento):** REQ-XXX\r\n**Clasificación:** Simple / Medio / Complejo\r\n**Vínculo operativo:** [enlace al proyecto/board en Azure DevOps o Wrike]\r\n\r\n> **Nota de uso:** el bloque **Epic** solo se instancia si la clasificación es **Complejo**. El bloque **Feature** solo se instancia si es **Medio** o **Complejo**. En **Simple**, se omiten ambos bloques y se va directo a User Story — el proyecto entero se trata como una sola unidad de trabajo.\r\n\r\n---\r\n\r\n## Reglas de negocio relevantes\r\n- [Regla 1]\r\n- [Regla 2]\r\n\r\n---\r\n\r\n## Epic — **solo si Complejo** (omitir este bloque en Simple/Medio)\r\n\r\n**EPIC-XXX — [Nombre]**\r\nDescripción de la iniciativa grande que agrupa las features siguientes. Propuesta por el agente durante `/bossdream-project` a partir del contexto de entrada, confirmada por el usuario.\r\n\r\n---\r\n\r\n## Feature — **solo si Medio o Complejo** (omitir este bloque en Simple)\r\n\r\n**FEAT-XXX — [Nombre]**\r\nDescripción de la capacidad o bloque funcional. Pertenece a: EPIC-XXX (si aplica clasificación Complejo).\r\n\r\n---\r\n\r\n## User Stories — siempre presente\r\n\r\n### US-XXX — [Nombre corto]\r\n**Pertenece a:** FEAT-XXX (si aplica)\r\n**Prioridad:** Alta / Media / Baja (Value vs. Effort)\r\n\r\n> Como [tipo de usuario/rol],\r\n> quiero [acción o capacidad],\r\n> para [beneficio de negocio].\r\n\r\n*(Variante técnica, cuando no hay un \"usuario\" claro — ej. integraciones):*\r\n> El sistema debe [comportamiento esperado], cuando [condición/disparador], para que [resultado de negocio].\r\n\r\n**Reglas de negocio aplicables:** [referencia a la sección \"Reglas de negocio relevantes\" de este documento, si corresponde]\r\n\r\n**Dependencias:** [otras US, sistemas externos, aprobaciones pendientes]\r\n\r\n#### Criterios de aceptación\r\n\r\n- **AC-XXX.1:** [criterio claro, verificable, sin ambigüedad]\r\n- **AC-XXX.2:** [criterio claro, verificable, sin ambigüedad]\r\n\r\n*(Usar Given/When/Then solo si el escenario tiene lógica condicional real que lo justifique):*\r\n> Dado que [contexto], cuando [acción], entonces [resultado esperado].\r\n\r\n**Pruebas relacionadas:** TC-XXX (ver `tests/cases/`)\r\n\r\n---\r\n\r\n*(Repetir bloque \"User Story\" por cada US de la iniciativa)*\r\n\r\n---\r\n\r\n## Tabla resumen de trazabilidad\r\n\r\n> Se sincroniza con `.bossdream-project/traceability.json` — no es la fuente de verdad, es una vista legible. En Simple/Medio se omiten las columnas Epic/Feature que no apliquen.\r\n\r\n| Epic | Feature | User Story | AC | Test Case | Prioridad | Estado |\r\n|---|---|---|---|---|---|---|\r\n| EPIC-XXX | FEAT-XXX | US-XXX | AC-XXX.1, AC-XXX.2 | TC-XXX | Alta | En progreso / Listo / Bloqueado |\r\n\r\n> El campo \"Estado\" se mantiene actualizado en la herramienta operativa (Azure DevOps/Wrike); esta tabla se sincroniza en los cierres de fase, no en tiempo real, para evitar doble mantenimiento.\r\n"},{"path":"_PROJECT_TEMPLATE/roadmap.md","note":"","content":"# Plan — Indice/Rollup — [Nombre del proyecto]\r\n\r\n> Generado por `/bossdream-plan` (extension via el hook `plan-context-inject.ps1` — `commands/bossdream-plan.md` no se modifica, decision 10). Este archivo es un **indice**, NO un `plan.md` ejecutable — `/bossdream-implement` no lo lee. Cada Feature conserva su propio `plans/<feature>/plan.md` de siempre (decision 8).\r\n\r\n## Epics / Features\r\n\r\n| Epic | Feature | Estado | plans/ |\r\n|---|---|---|---|\r\n| [EPIC-XXX o \"—\" si Medio/Simple] | [FEAT-XXX o \"—\" si Simple] | pendiente / planeada / en progreso / hecha | `plans/<feature>/` |\r\n\r\n## QA Increment\r\n\r\nSe agrega siempre como la ultima Feature del rollup, nunca se omite.\r\n\r\n| Feature | Estado | plans/ |\r\n|---|---|---|\r\n| QA Increment | pendiente | `plans/<slug>-qa-increment/` |\r\n\r\n## Progreso de planeacion multi-sesion\r\n\r\nVer `.bossdream-project/plan-progress.json` para el detalle exacto de que Epic/Feature ya se planeo y que queda pendiente — este archivo no duplica ese detalle, solo referencia el estado agregado.\r\n"},{"path":"_PROJECT_TEMPLATE/tests/test-approach.md","note":"","content":"# Enfoque de Pruebas — [Nombre de la iniciativa]\r\n\r\n**ID de iniciativa:** REQ-XXX\r\n**Clasificación:** Simple / Medio / Complejo\r\n\r\n> **AVISO:** este documento se genera crudo, con placeholders — requiere llenado manual completo antes de `/bossdream-validate`. Los casos de prueba formales individuales viven en `cases/TC-XXX.md` (uno por archivo, vía `/bossdream-testcase`) — no se embeben aquí.\r\n\r\n---\r\n\r\n## 1. Cuándo usar checklist vs. casos de prueba formales\r\n\r\n| Nivel | Enfoque |\r\n|---|---|\r\n| **Simple** | Solo checklist de smoke test (sección 2). No se crean casos de prueba formales. |\r\n| **Medio** | Checklist + casos de prueba formales (`cases/TC-XXX.md`) solo para lo crítico y para lo que tenga lógica condicional relevante. |\r\n| **Complejo** | Casos de prueba formales completos + regresión + prueba de integración si aplica + revisión de seguridad si toca datos sensibles. |\r\n\r\n---\r\n\r\n## 2. Checklist de smoke test (Simple, y como base en Medio/Complejo)\r\n\r\n- [ ] La funcionalidad principal responde sin errores.\r\n- [ ] No se rompió nada que funcionaba antes (revisión rápida de lo relacionado).\r\n- [ ] Los datos se guardan/consultan correctamente en el ambiente de pruebas.\r\n- [ ] El usuario que validó (UAT) confirmó que ve lo esperado.\r\n\r\n**Evidencia mínima:** captura de pantalla o confirmación escrita de quien ejecutó la checklist — guardar en `evidencia/`.\r\n\r\n---\r\n\r\n## 3. Casos de prueba formales — ver `cases/TC-XXX.md`\r\n\r\nLos casos de prueba individuales (Medio y Complejo) se generan uno por uno vía `/bossdream-testcase` usando la plantilla `_templates/test-case.md`. No se listan en este archivo para evitar reescribir un documento monolítico en cada caso nuevo — ver tabla resumen abajo (sección 7) para el estado agregado.\r\n\r\n---\r\n\r\n## 4. Regresión (Medio y Complejo)\r\n\r\nLista de funcionalidades existentes que podrían verse afectadas por este cambio y que deben re-verificarse:\r\n\r\n- [ ] [Funcionalidad existente 1]\r\n- [ ] [Funcionalidad existente 2]\r\n\r\n---\r\n\r\n## 5. Pruebas de integración (cuando aplica)\r\n\r\nPara iniciativas que involucran comunicación entre sistemas:\r\n\r\n| Sistema origen | Sistema destino | Escenario probado | Resultado |\r\n|---|---|---|---|\r\n| | | | |\r\n\r\n---\r\n\r\n## 6. Revisión de seguridad (Complejo, cuando toca datos financieros/nómina o sensibles)\r\n\r\n- [ ] Los datos sensibles no quedan expuestos en logs, respuestas de API o pantallas sin control de acceso.\r\n- [ ] Los permisos/roles de acceso se validaron para el nuevo flujo.\r\n- [ ] Si aplica, se validó que la integración usa un canal seguro.\r\n\r\n---\r\n\r\n## 7. Resumen de evidencia para cierre de QA\r\n\r\n| Total de casos | Pasaron | Fallaron | Bloqueados | ¿Listo para UAT? |\r\n|---|---|---|---|---|\r\n| | | | | Sí / No |\r\n\r\n> Esta tabla la actualiza `testcase-register.ps1` cada vez que se registra un `TC-XXX.md` nuevo — no editar a mano el conteo.\r\n"},{"path":"_PROJECT_TEMPLATE/tests/_templates/test-case.md","note":"","content":"# TC-XXX — [Nombre del escenario]\r\n\r\n**Relacionado con:** US-XXX / AC-XXX.N\r\n\r\n| Campo | Detalle |\r\n|---|---|\r\n| **Escenario** | [qué se está probando] |\r\n| **Precondiciones** | [qué debe existir/estar configurado antes de probar] |\r\n| **Datos de prueba** | [qué datos se usan] |\r\n| **Pasos** | 1. [...] 2. [...] 3. [...] |\r\n| **Resultado esperado** | [qué debería pasar] |\r\n| **Resultado obtenido** | [qué pasó realmente] |\r\n| **Evidencia** | [captura, log, enlace — guardar en `../evidence/`] |\r\n| **Estado** | Pasó / Falló / Bloqueado |\r\n"},{"path":"_PROJECT_TEMPLATE/understanding.md","note":"","content":"# Documento de Entendimiento — [Nombre corto de la iniciativa]\r\n\r\n> **¿Qué es este documento?** Es donde dejamos por escrito qué entendimos que necesitas y qué vamos a construir, para que lo puedas leer y confirmarnos: *\"sí, esto es exactamente lo que necesito\"*. No contiene lenguaje técnico.\r\n\r\n**ID de iniciativa:** REQ-XXX\r\n**Fecha:** [fecha]\r\n**Solicitado por:** [nombre / área / empresa del grupo]\r\n**Preparado por:** [nombre]\r\n**Clasificación (uso interno del equipo):** Simple / Medio / Complejo\r\n\r\n---\r\n\r\n## 1. ¿Cuál es el problema o la necesidad?\r\n[Descripción breve, en palabras del negocio, de qué está pasando o qué se necesita resolver.]\r\n\r\n## 2. Contexto\r\n[Por qué surge esta necesidad ahora. Qué la originó.]\r\n\r\n## 3. Objetivo\r\n[Qué se espera lograr con esta solución, en una o dos frases.]\r\n\r\n## 4. ¿Quién usa esto?\r\n[Áreas, roles o personas que van a usar la solución.]\r\n\r\n## 5. Alcance — qué vamos a construir\r\n- [Punto 1]\r\n- [Punto 2]\r\n- [...]\r\n\r\n## 6. Fuera de alcance — qué NO vamos a construir\r\n- [Punto 1]\r\n- [Punto 2]\r\n\r\n> *Esta sección es tan importante como la anterior. Si algo no está aquí ni en el alcance, se considera no incluido.*\r\n\r\n## 7. Proceso actual (si aplica)\r\n[Cómo se hace hoy, si ya existe un proceso que se va a reemplazar o mejorar.]\r\n\r\n## 8. Proceso propuesto\r\n[Cómo se haría con la solución, en lenguaje de negocio — sin detalles técnicos.]\r\n\r\n## 9. Reglas de negocio relevantes\r\n- [Regla 1]\r\n- [Regla 2]\r\n\r\n## 10. Dependencias y supuestos\r\n- **Dependencias:** [de qué depende esto para poder avanzar]\r\n- **Supuestos:** [qué estamos asumiendo que es verdad]\r\n\r\n## 11. Restricciones conocidas\r\n[Ej. fecha límite, presupuesto, disponibilidad de alguna persona clave.]\r\n\r\n## 12. Riesgos conocidos\r\n[Qué podría salir mal o retrasar esta iniciativa.]\r\n\r\n## 13. Criterios de éxito\r\n[Cómo sabremos que esto funcionó — en términos de negocio, no técnicos.]\r\n\r\n---\r\n\r\n## 14. Aprobación\r\n\r\n> Selecciona el mecanismo que aplique para esta área:\r\n\r\n**Opción A — Aprobación formal**\r\n☐ Confirmo que este documento refleja correctamente lo que necesito.\r\n\r\nNombre: _______________  Fecha: _______________  Firma/checkbox: _______________\r\n\r\n**Opción B — Confirmación ligera**\r\nConfirmado por: [nombre] el [fecha], vía [correo / chat / llamada] — referencia: [enlace o descripción breve de dónde queda constancia].\r\n\r\n---\r\n\r\n## 15. Historial de cambios\r\n*(se llena solo si algo cambia después de la aprobación inicial — ver Sección 9 del SDLC del equipo)*\r\n\r\n| Fecha | Qué cambió | Solicitado por | Impacto (tiempo/alcance) | ¿Requirió nueva aprobación? |\r\n|---|---|---|---|---|\r\n| | | | | |\r\n"}],"dotnet":[{"path":"ci/quality-gate.yml","note":"","content":"name: quality-gate\r\non:\r\n  pull_request:\r\n  push:\r\n    branches: [main, develop]\r\n\r\njobs:\r\n  pipeline:\r\n    runs-on: windows-latest\r\n    steps:\r\n      - uses: actions/checkout@v4\r\n      - uses: actions/setup-dotnet@v4\r\n        with:\r\n          dotnet-version: '10.0.x'\r\n      - name: Build (warnings as errors)\r\n        shell: pwsh\r\n        run: dotnet build -warnaserror\r\n      - name: Format\r\n        shell: pwsh\r\n        run: dotnet format --verify-no-changes\r\n      - name: Test\r\n        shell: pwsh\r\n        run: dotnet test\r\n"},{"path":"CLAUDE.stack.md","note":"Punto de partida para la sección Stack de CLAUDE.md.","content":"## Stack\n\n- **Lenguaje/runtime:** .NET (versión: <completar, ej. .NET 8/9/10>)\n- **Framework de UI:** <completar, ej. Blazor Server/WASM, ASP.NET Core MVC, XAF, WinForms, consola>\n- **ORM:** <completar, ej. EF Core, XPO, Dapper>\n- **Base de datos:** <completar>\n- **Test runner:** <completar, ej. xUnit, NUnit, MSTest> + Stryker.NET (mutación)\n- **Convenciones propias del equipo:** <completar>\n"},{"path":"codeExtensions.json","note":"Extensiones de código que leen los hooks.","content":"[\".cs\", \".razor\", \".csproj\", \".props\", \".targets\"]\n"},{"path":"editorconfig.snippet","note":"Fragmento de .editorconfig del lenguaje.","content":"[*.cs]\r\nindent_style = space\r\nindent_size = 4\r\ncsharp_style_namespace_declarations = file_scoped:error\r\ndotnet_diagnostic.IDE0005.severity = error\r\n"},{"path":"pipeline.json","note":"Etapas agnósticas del pipeline (theme-check, gherkin, docdrift).","content":"{\r\n  \"stages\": [\r\n    { \"id\": \"build\", \"order\": 1, \"cmd\": \"dotnet build -warnaserror\", \"tier\": \"local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"format\", \"order\": 2, \"cmd\": \"dotnet format --verify-no-changes\", \"tier\": \"local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"theme-check\", \"order\": 3, \"internal\": \"style-check\", \"tier\": \"local\", \"blocking\": \"hard\", \"requiresStyle\": true },\r\n    { \"id\": \"gherkin\", \"order\": 4, \"internal\": \"gherkin-check\", \"tier\": \"local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"arch\", \"order\": 5, \"cmd\": \"dotnet test tests/Arch\", \"tier\": \"local\", \"blocking\": \"hard\", \"enabled\": false },\r\n    { \"id\": \"unit\", \"order\": 6, \"cmd\": \"dotnet test ${testProject} /p:CollectCoverage=true /p:Threshold=80\", \"tier\": \"local\", \"blocking\": \"hard\", \"requiresTesting\": true },\r\n    { \"id\": \"integration\", \"order\": 7, \"cmd\": \"dotnet test tests/Integration\", \"tier\": \"ci\", \"blocking\": \"hard\", \"enabled\": false },\r\n    { \"id\": \"bdd\", \"order\": 8, \"cmd\": \"dotnet test ${testProject} --filter Category=bdd\", \"tier\": \"ci\", \"blocking\": \"hard\", \"requiresBdd\": true },\r\n    { \"id\": \"e2e\", \"order\": 9, \"cmd\": \"dotnet test tests/E2E\", \"tier\": \"ci\", \"blocking\": \"hard\", \"enabled\": false },\r\n    { \"id\": \"mutation\", \"order\": 10, \"cmd\": \"dotnet stryker\", \"tier\": \"local\", \"blocking\": \"hard\", \"requiresTesting\": true },\r\n    { \"id\": \"docdrift\", \"order\": 11, \"internal\": \"docdrift-check\", \"tier\": \"ci\", \"blocking\": \"soft\", \"enabled\": false }\r\n  ]\r\n}\r\n"},{"path":"settings.snippet.json","note":"Permisos de Bash del lenguaje.","content":"{\n  \"permissions\": {\n    \"allow\": [\n      \"Bash(dotnet build*)\",\n      \"Bash(dotnet format*)\",\n      \"Bash(dotnet test*)\",\n      \"Bash(dotnet stryker*)\"\n    ]\n  }\n}\n"},{"path":"stryker-config.json","note":"Configuración de mutation testing.","content":"{\n  \"stryker-config\": {\n    \"mutation-level\": \"Standard\",\n    \"reporters\": [\"html\", \"progress\"],\n    \"thresholds\": { \"high\": 80, \"low\": 60, \"break\": 0 }\n  }\n}\n"}],"nodejs":[{"path":"ci/quality-gate.yml","note":"","content":"name: quality-gate\r\non:\r\n  pull_request:\r\n  push:\r\n    branches: [main, develop]\r\n\r\njobs:\r\n  pipeline:\r\n    runs-on: ubuntu-latest\r\n    steps:\r\n      - uses: actions/checkout@v4\r\n      - uses: actions/setup-node@v4\r\n        with:\r\n          node-version: '22.x'\r\n      - name: Install\r\n        run: npm ci\r\n      - name: Build (type-check)\r\n        run: npx tsc --noEmit\r\n      - name: Format\r\n        run: npx prettier --check .\r\n      - name: Test\r\n        run: npx vitest run --coverage\r\n"},{"path":"CLAUDE.stack.md","note":"Punto de partida para la sección Stack de CLAUDE.md.","content":"## Stack\n\n- **Lenguaje/runtime:** Node/TypeScript (versión: <completar>)\n- **Framework de UI:** <completar, ej. Vue 3, React, Tauri+Vue, Svelte, ninguno (backend puro)>\n- **Bundler:** <completar, ej. Vite, Webpack>\n- **Gestor de paquetes:** <completar, ej. npm, pnpm, yarn>\n- **Test runner:** Vitest + Stryker JS (mutación)\n- **Convenciones propias del equipo:** <completar>\n"},{"path":"codeExtensions.json","note":"Extensiones de código que leen los hooks.","content":"[\".js\", \".ts\", \".jsx\", \".tsx\", \".vue\"]\n"},{"path":"editorconfig.snippet","note":"Fragmento de .editorconfig del lenguaje.","content":"[*.{js,ts,jsx,tsx,vue}]\r\nindent_style = space\r\nindent_size = 2\r\nquote_type = single\r\n"},{"path":"pipeline.json","note":"Etapas agnósticas del pipeline (theme-check, gherkin, docdrift).","content":"{\r\n  \"stages\": [\r\n    { \"id\": \"build\", \"order\": 1, \"cmd\": \"npx tsc --noEmit\", \"tier\": \"local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"format\", \"order\": 2, \"cmd\": \"npx prettier --check .\", \"tier\": \"local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"theme-check\", \"order\": 3, \"internal\": \"style-check\", \"tier\": \"local\", \"blocking\": \"hard\", \"requiresStyle\": true },\r\n    { \"id\": \"gherkin\", \"order\": 4, \"internal\": \"gherkin-check\", \"tier\": \"local\", \"blocking\": \"hard\" },\r\n    { \"id\": \"arch\", \"order\": 5, \"cmd\": \"npx dependency-cruiser --validate src\", \"tier\": \"local\", \"blocking\": \"hard\", \"enabled\": false },\r\n    { \"id\": \"unit\", \"order\": 6, \"cmd\": \"npx vitest run --coverage\", \"tier\": \"local\", \"blocking\": \"hard\", \"requiresTesting\": true },\r\n    { \"id\": \"integration\", \"order\": 7, \"cmd\": \"npx vitest run tests/integration\", \"tier\": \"ci\", \"blocking\": \"hard\", \"enabled\": false },\r\n    { \"id\": \"bdd\", \"order\": 8, \"cmd\": \"npx cucumber-js\", \"tier\": \"ci\", \"blocking\": \"hard\", \"requiresBdd\": true },\r\n    { \"id\": \"e2e\", \"order\": 9, \"cmd\": \"npx playwright test\", \"tier\": \"ci\", \"blocking\": \"hard\", \"enabled\": false },\r\n    { \"id\": \"mutation\", \"order\": 10, \"cmd\": \"npx stryker run\", \"tier\": \"local\", \"blocking\": \"hard\", \"requiresTesting\": true },\r\n    { \"id\": \"docdrift\", \"order\": 11, \"internal\": \"docdrift-check\", \"tier\": \"ci\", \"blocking\": \"soft\", \"enabled\": false }\r\n  ]\r\n}\r\n"},{"path":"settings.snippet.json","note":"Permisos de Bash del lenguaje.","content":"{\n  \"permissions\": {\n    \"allow\": [\n      \"Bash(npm run*)\",\n      \"Bash(npm ci*)\",\n      \"Bash(npx tsc*)\",\n      \"Bash(npx eslint*)\",\n      \"Bash(npx prettier*)\",\n      \"Bash(npx vitest*)\",\n      \"Bash(npx stryker*)\"\n    ]\n  }\n}\n"},{"path":"stryker-config.json","note":"Configuración de mutation testing.","content":"{\n  \"$schema\": \"./node_modules/@stryker-mutator/core/schema/stryker-schema.json\",\n  \"packageManager\": \"npm\",\n  \"testRunner\": \"vitest\",\n  \"mutate\": [\"src/**/*.ts\", \"src/**/*.js\"],\n  \"reporters\": [\"html\", \"progress\"],\n  \"coverageAnalysis\": \"perTest\",\n  \"thresholds\": { \"high\": 80, \"low\": 60, \"break\": 0 }\n}\n"},{"path":"vitest.config.ts","note":"Configuración de Vitest con cobertura.","content":"import { defineConfig } from 'vitest/config'\r\n\r\nexport default defineConfig({\r\n  test: {\r\n    environment: 'node',\r\n    coverage: {\r\n      provider: 'v8',\r\n      reporter: ['text', 'html'],\r\n      include: ['src/**/*.{js,ts}'],\r\n    },\r\n  },\r\n})\r\n"}]},"pipeline":{"dotnet":[{"id":"build","order":1,"cmd":"dotnet build -warnaserror","tier":"local","blocking":"hard","enabled":true},{"id":"format","order":2,"cmd":"dotnet format --verify-no-changes","tier":"local","blocking":"hard","enabled":true},{"id":"theme-check","order":3,"cmd":"interno: style-check","tier":"local","blocking":"hard","enabled":true},{"id":"gherkin","order":4,"cmd":"interno: gherkin-check","tier":"local","blocking":"hard","enabled":true},{"id":"arch","order":5,"cmd":"dotnet test tests/Arch","tier":"local","blocking":"hard","enabled":false},{"id":"unit","order":6,"cmd":"dotnet test ${testProject} /p:CollectCoverage=true /p:Threshold=80","tier":"local","blocking":"hard","enabled":true},{"id":"integration","order":7,"cmd":"dotnet test tests/Integration","tier":"ci","blocking":"hard","enabled":false},{"id":"bdd","order":8,"cmd":"dotnet test ${testProject} --filter Category=bdd","tier":"ci","blocking":"hard","enabled":true},{"id":"e2e","order":9,"cmd":"dotnet test tests/E2E","tier":"ci","blocking":"hard","enabled":false},{"id":"mutation","order":10,"cmd":"dotnet stryker","tier":"local","blocking":"hard","enabled":true},{"id":"docdrift","order":11,"cmd":"interno: docdrift-check","tier":"ci","blocking":"soft","enabled":false}],"nodejs":[{"id":"build","order":1,"cmd":"npx tsc --noEmit","tier":"local","blocking":"hard","enabled":true},{"id":"format","order":2,"cmd":"npx prettier --check .","tier":"local","blocking":"hard","enabled":true},{"id":"theme-check","order":3,"cmd":"interno: style-check","tier":"local","blocking":"hard","enabled":true},{"id":"gherkin","order":4,"cmd":"interno: gherkin-check","tier":"local","blocking":"hard","enabled":true},{"id":"arch","order":5,"cmd":"npx dependency-cruiser --validate src","tier":"local","blocking":"hard","enabled":false},{"id":"unit","order":6,"cmd":"npx vitest run --coverage","tier":"local","blocking":"hard","enabled":true},{"id":"integration","order":7,"cmd":"npx vitest run tests/integration","tier":"ci","blocking":"hard","enabled":false},{"id":"bdd","order":8,"cmd":"npx cucumber-js","tier":"ci","blocking":"hard","enabled":true},{"id":"e2e","order":9,"cmd":"npx playwright test","tier":"ci","blocking":"hard","enabled":false},{"id":"mutation","order":10,"cmd":"npx stryker run","tier":"local","blocking":"hard","enabled":true},{"id":"docdrift","order":11,"cmd":"interno: docdrift-check","tier":"ci","blocking":"soft","enabled":false}]},"debt":[{"id":"TD-001","where":"templates/bossdream.json vs scripts/sync-agent-models.ps1","kind":"consistencia","problem":"La plantilla define `models.plan/code/audit/quick`; el script lee `models.default/agents` y solo actua sobre `plugins/bossdream-core/agents` del propio repo","fix":"Unificar el esquema y decidir si el script es herramienta del framework o de proyectos","severity":"medium","status":"open"},{"id":"TD-002","where":"hooks de .claude/bossdream-hooks/","kind":"portabilidad","problem":"Los hooks se copian al proyecto con `/bossdream-init`; moverlos a `hooks/hooks.json` del plugin evitaria la copia y el drift, pero obliga a rehacer la resolucion de scripts hermanos (`plugin-paths.psm1` busca `<proyecto>/plugins`)","fix":"Redisenar con `${CLAUDE_PLUGIN_ROOT}` y migrar las pruebas de hermanos","severity":"high","status":"open"},{"id":"TD-003","where":"scripts/*.ps1","kind":"encoding","problem":"Varios `Get-Content` sin `-Encoding utf8` leen mal UTF-8 sin BOM en Windows PowerShell 5.1","fix":"Fijar `-Encoding utf8` en las lecturas o dejar PowerShell 7 como unico host","severity":"low","status":"paid"},{"id":"TD-004","where":"regla de comentarios","kind":"experiencia","problem":"La regla solo llega al proyecto con `/bossdream-init` (`.claude/rules/comentarios.md`)","fix":"Inyectarla con un hook `SessionStart` del plugin cuando exista `hooks.json` (TD-002)","severity":"low","status":"open"},{"id":"TD-005","where":"scripts/plan-lock.ps1, readiness.ps1","kind":"seguridad","problem":"El mode-lock lee `.claude/.work-mode` de `cwd` del payload: si la sesion tiene como directorio de trabajo una subcarpeta del proyecto, no encuentra el archivo y el bloqueo no se aplica (observado en esta sesion al editar `.ps1` desde `plugins/bossdream-core`)","fix":"Resolver la raiz del proyecto con `CLAUDE_PROJECT_DIR` o subiendo hasta encontrar `.claude/`","severity":"medium","status":"paid"}],"hooks":["active-project-context","bossdream-learning-gate","bossdream-learning-publish","command-lock","comment-check","context-router-log","docdrift-check","emergency-override","execution-checks","flow-coverage-check","gherkin-check","hook-siblings-sync","mark-dirty","mark-project-dirty","pattern-detect","pipeline","plan-artifact-consume","plan-checks","plan-context-inject","plan-lock","plan-progress-update","project-scaffold","project-sync","read-budget","readiness","set-active-project","smoker-log-append","sobriety-audit","stop-completion","style-check","sync-agent-models","tasks-complete","test-checks","test-inventory-check","testcase-register","traceability-build","validation-check","validation-exemption-check","validation-lock","validation-mark-mechanical","validation-structure-check","validation-trace-check","validation-vale-check"]};
